function fitModalToVisualViewport(){const root=$('#modalRoot'),backdrop=root?.querySelector('.modal-backdrop'),panel=root?.querySelector('.modal');if(!backdrop||!panel)return;const vv=window.visualViewport;if(vv){backdrop.style.left=`${vv.offsetLeft}px`;backdrop.style.top=`${vv.offsetTop}px`;backdrop.style.width=`${vv.width}px`;backdrop.style.height=`${vv.height}px`;backdrop.style.right='auto';backdrop.style.bottom='auto';panel.style.maxWidth=`calc(${vv.width}px - 16px)`;panel.style.maxHeight=`calc(${vv.height}px - 16px)`;}else{backdrop.style.left='0';backdrop.style.top='0';backdrop.style.width='100vw';backdrop.style.height='100dvh';}}
