 const action=a.fiveSAction?btn('Resolve →',`data-resolve-five-s-action="${esc(a.id)}"`,'button small primary'):a.improvementProposalId?btn(implemented?'Implemented ✓':'Continue implementation →',`data-implement-improvement="${esc(a.id)}"`,'button small primary'):(a.requestId||a.careItemKey)?btn(a.careItemKey?'Complete →':'Resolve →',`data-resolve-action="${esc(a.id)}"`,'button small primary'):btn('Review →',`data-nav="${esc(a.resolve||'action-centre')}"`,'button small secondary');
