 return `<div class="action-item"><div class="action-stripe ${a.severity||''}"></div><div><h3>${esc(a.title)}</h3><div class="subtle"><strong>${esc(a.category)}</strong> · ${esc(a.requestId||'General')}</div><div class="action-meta"><span>Why: ${esc(a.why)}</span><span>Impact: ${esc(a.impact)}</span><span>Owner: ${esc(a.owner)}</span><span>Due: ${P.formatDate(a.due)}</span>${implementation}</div></div><div>${action}</div></div>`
