function parseCsv(text){text=String(text??'').replace(/^\uFEFF/,'');const first=(text.split(/\r?\n/).find(x=>x.trim())||''),count=d=>{let q=false,n=0;for(let i=0;i<first.length;i++){const c=first[i];if(c==='"'){if(q&&first[i+1]==='"')i++;else q=!q}else if(!q&&c===d)n++}return n},delimiter=[',',';','\t'].sort((a,b)=>count(b)-count(a))[0],rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted;continue}if(!quoted&&c===delimiter){row.push(cell);cell='';continue}if(!quoted&&(c==='\n'||c==='\r')){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);cell='';if(row.some(x=>String(x).trim()!==''))rows.push(row);row=[];continue}cell+=c}row.push(cell);if(row.some(x=>String(x).trim()!==''))rows.push(row);rows.delimiter=delimiter;return rows}
