 const people=(App.state.staff||[]).filter(x=>x.available!==false),equipment=(App.state.equipment||[]).filter(e=>P.projectedEquipmentReady?P.projectedEquipmentReady(App.state,e,mid):P.equipmentReady(e,mid,App.state));
