 const scored=resources.map(res=>{const periods=buckets.map(b=>{const rows=filteredRows.filter(x=>inWindow(x.start,b.start,b.end)&&(type==='person'?(x.staffId===res.id||x.person===res.name):(x.equipmentId===res.id||x.equipment===res.name))),wd=opsWorkdays(b.start,b.end),mid=new Date((b.start.getTime()+b.end.getTime())/2).toISOString().slice(0,10),available=type==='person'?res.available!==false:(P.projectedEquipmentReady?P.projectedEquipmentReady(App.state,res,mid):P.equipmentReady(res,mid,App.state)),cap=available?weekly/5*wd:0,load=sumHours(rows);return {load,cap,util:opsPct(load,cap)}});return {res,periods,peak:Math.max(...periods.map(x=>x.util))}}).filter(x=>x.peak>0||x.periods.some(p=>p.load>0)).sort((a,b)=>b.peak-a.peak).slice(0,8);
 return `<div class="card"><div class="section-title-row"><div><span class="eyebrow">${esc(type==='person'?'PEOPLE':'EQUIPMENT')} CAPACITY</span><h2>${esc(title)}</h2><div class="subtle">Filtered build demand is compared with total currently available lab capacity for each resource.</div></div></div><div class="table-wrap"><table class="data-table ops-cap-table"><thead><tr><th>${type==='person'?'Person':'Equipment'}</th>${buckets.map(b=>`<th>${esc(b.label)}<small>${esc(b.dateLabel)}</small></th>`).join('')}</tr></thead><tbody>${scored.map(x=>`<tr><td><strong>${esc(x.res.name)}</strong><small>${esc(type==='person'?(x.res.role||'Lab staff'):(x.res.capability||'Equipment'))}</small></td>${x.periods.map(p=>`<td>${opsUtilCell(p.load,p.cap)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="4">No workload is assigned to these resources in the selected horizon.</td></tr>`}</tbody></table></div></div>`
