 const compare=(a,b)=>{if(sortBy==='submitted-asc')return new Date(a.submittedAt||a.createdAt)-new Date(b.submittedAt||b.createdAt);if(sortBy==='required-asc')return String(a.requiredDate||'').localeCompare(String(b.requiredDate||''));if(sortBy==='required-desc')return String(b.requiredDate||'').localeCompare(String(a.requiredDate||''));if(sortBy==='product')return String(a.productFamily||'').localeCompare(String(b.productFamily||''))||String(a.requiredDate||'').localeCompare(String(b.requiredDate||''));if(sortBy==='customer')return String(customerName(a.customerId)).localeCompare(String(customerName(b.customerId)))||String(a.requiredDate||'').localeCompare(String(b.requiredDate||''));if(sortBy==='priority')return (priorityRank[a.priority]??9)-(priorityRank[b.priority]??9)||String(a.requiredDate||'').localeCompare(String(b.requiredDate||''));return new Date(b.submittedAt||b.createdAt)-new Date(a.submittedAt||a.createdAt)};
 const filtered=App.state.requests.filter(r=>{const isArchived=!!(r.archived||r.status==='CLOSED'),date=String(r.submittedAt||r.createdAt||'').slice(0,10),hay=[r.id,r.title,r.productFamily,r.programme,r.owner,r.requester,r.engineeringTeam,customerName(r.customerId)].join(' ').toLowerCase();return (archive==='all'||(archive==='archived'?isArchived:!isArchived))&&(!search||hay.includes(search))&&(!product||r.productId===product)&&(!customer||r.customerId===customer)&&(!project||r.programme===project)&&(!owner||r.owner===owner)&&(!submitter||r.requester===submitter)&&(!from||date>=from)&&(!to||date<=to)}).sort(compare);
 const active=App.state.requests.filter(r=>!(r.archived||r.status==='CLOSED')).length,archived=App.state.requests.length-active;
 return pageHeader('Prototype Builds','Search, sort and open active or archived prototype builds.',can('request:create')?btn('+ New prototype request','data-new-request','button primary'):'')+`<div class="request-archive-tabs"><button class="filter-chip ${archive==='active'?'active':''}" data-req-archive="active">Active <b>${active}</b></button><button class="filter-chip ${archive==='archived'?'active':''}" data-req-archive="archived">Archived <b>${archived}</b></button><button class="filter-chip ${archive==='all'?'active':''}" data-req-archive="all">All <b>${App.state.requests.length}</b></button>${archived===0&&P.isDemoDataset(App.state)?btn('Add 3 archived demo builds','data-install-demo-archive','button secondary'):''}</div><div class="card request-search-panel"><div class="request-search-grid"><label>Search<input id="reqSearch" value="${esc(App.filters.reqSearch||'')}" placeholder="Build, product, customer…"></label><label>Sort<select id="reqSort">${[['submitted-desc','Newest submitted'],['submitted-asc','Oldest submitted'],['required-asc','Required date ↑'],['required-desc','Required date ↓'],['product','Product'],['customer','Customer'],['priority','Priority']].map(([v,l])=>`<option value="${v}" ${sortBy===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Product<select id="reqProduct"><option value="">All</option>${App.state.products.map(p=>`<option value="${p.id}" ${product===p.id?'selected':''}>${esc(p.family)}</option>`).join('')}</select></label><label>Customer<select id="reqCustomer"><option value="">All</option>${App.state.customers.map(c=>`<option value="${c.id}" ${customer===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Project<select id="reqProject"><option value="">All</option>${projects.map(x=>`<option ${project===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Owner<select id="reqOwner"><option value="">All</option>${owners.map(x=>`<option ${owner===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Submitter<select id="reqSubmitter"><option value="">All</option>${submitters.map(x=>`<option ${submitter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>From<input id="reqFrom" type="date" value="${esc(from)}"></label><label>To<input id="reqTo" type="date" value="${esc(to)}"></label>${btn('Clear','data-clear-request-search','button secondary')}</div></div>${requestTable(filtered,archive==='archived'?'Completed / archived projects':archive==='active'?'Active request portfolio':'All prototype projects')}`;
