const FIVE_S_PILLARS=[
 ['sort','Sort','Remove what is not needed; red-tag or disposition abnormal items.'],
 ['set','Set in order','Give required items a defined, visible and ergonomic location.'],
 ['shine','Shine','Clean while checking for abnormal conditions and deterioration.'],
 ['standardize','Standardize','Maintain visual standards, ownership and repeatable checks.'],
 ['sustain','Sustain','Demonstrate adherence, follow-up and continued discipline.']
];
