function fiveSAuditModal(zoneId){
 P.ensureEnterpriseModel(App.state);const z=(App.state.fiveSZones||[]).find(x=>x.id===zoneId);if(!z)return;
 openModal(`5S check · ${z.name}`,`<div class="callout"><strong>${esc(z.area)} · owner ${esc(z.owner)}</strong><p>Score the observed condition, not the intention. Scores below 4 create a guided action assigned to the zone owner.</p></div><div class="five-s-score-list">${FIVE_S_PILLARS.map(([id,label,help])=>`<div class="five-s-score-row"><div><strong>${label}</strong><small>${esc(help)}</small></div><select data-5s-score="${id}"><option value="5">5 · Sustained</option><option value="4">4 · Meets standard</option><option value="3" selected>3 · Improvement needed</option><option value="2">2 · Significant gap</option><option value="1">1 · Major gap</option></select></div>`).join('')}</div><div class="field"><label>Evidence / observation</label><textarea id="fsEvidence" placeholder="What was observed? Link/photo/reference if available."></textarea></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Record 5S check','data-save-5s-audit','button primary')}`,true);
 setTimeout(()=>{$('[data-save-5s-audit]').onclick=async()=>{const scores={};$$('[data-5s-score]').forEach(x=>scores[x.dataset['5sScore']]=Number(x.value));const evidence=$('#fsEvidence').value.trim(),audit={id:P.uid('5S-AUDIT'),zoneId:z.id,date:P.now(),auditor:App.state.identity.name,scores,evidence,average:Object.values(scores).reduce((a,b)=>a+b,0)/5};App.state.fiveSAudits.push(audit);const due=new Date(Date.now()+7*86400000).toISOString().slice(0,10);for(const [key,label,help] of FIVE_S_PILLARS){if(scores[key]>=4)continue;App.state.actions.push({id:P.uid('ACT'),category:'5S',title:`5S · ${z.name} · ${label}`,why:`5S check scored ${scores[key]}/5. ${evidence||help}`,impact:'Workplace standard below target',owner:z.owner,due,severity:scores[key]<=2?'bad':'warn',fiveSAction:{auditId:audit.id,zoneId:z.id,pillar:key,pillarLabel:label,targetScore:4}})}P.audit(App.state,'5S workplace check recorded','5S Audit',audit.id,'—',`${audit.average.toFixed(1)}/5`,`${z.name} · ${App.state.actions.filter(a=>a.fiveSAction?.auditId===audit.id).length} action(s)`);await persist();closeModal();render();toast(`5S check recorded · ${audit.average.toFixed(1)}/5.`)}},0)
}
