 const svc=new P.ResourceCareService(),kind=['Calibration','Maintenance','Training'].includes(type)?type:'Maintenance',isTraining=kind==='Training',equip=App.state.equipment||[],staff=App.state.staff||[],skills=App.state.competencies||[],firstEq=equip[0],firstSkill=skills[0],defaultHours=isTraining?Number(firstSkill?.trainingDurationHours||4):Number(kind==='Calibration'?firstEq?.calibrationDurationHours||4:firstEq?.maintenanceDurationHours||4),start=careLocalDateTimeValue(new Date(Date.now()+24*3600000).toISOString());
