  const preview=()=>{const box=$('#newCarePreview');try{const item=buildItem(),pv=svc.previewSlot(App.state,item,st.value);if(pv.careConflicts.length||pv.eventConflicts.length)box.innerHTML=`<span class="status bad">✕ This time overlaps another fixed readiness/lab event</span><small>Use “Find resolvable slot”. LabOS will not create an unresolved collision.</small>`;else if(pv.affectedRequestIds.length)box.innerHTML=`<span class="status warn">● ${pv.affectedRequestIds.length} build plan${pv.affectedRequestIds.length===1?'':'s'} affected</span><small>Saving will automatically replan: ${pv.affectedRequestIds.map(esc).join(', ')}. You do not need to replan manually.</small>`;else box.innerHTML='<span class="status good">✓ Ready to schedule</span><small>No controlled-resource collision.</small>';}catch(e){box.innerHTML=`<span class="status bad">✕ ${esc(e.message)}</span>`}};
