function renderIntake(){
 return pageHeader('Requests','One front door for laboratory work. Prototype is operational now; Validation and Failure Analysis use the same intake architecture when implemented.')+`<div class="intake-workstream-grid"><article class="card intake-workstream-card active"><div class="intake-workstream-head"><span class="status good">✓ Operational</span><h2>Prototype</h2><p>Request a prototype device/product, define configuration, quantity, required date and engineering purpose, then flow through feasibility, planning, build, quality and release.</p></div><div class="route-toolbar">${can('request:create')?btn('+ New prototype request','data-new-request','button primary'):''}${btn('Open prototype queue','data-nav="requests"','button secondary')}</div></article><article class="card intake-workstream-card future"><div class="intake-workstream-head"><span class="status neutral">Future</span><h2>Validation</h2><p>DV/PV, engineering validation and reliability requests will start from requirement/specification intent, required DUT population and target evidence, with method-development gaps routed automatically.</p></div><small>Uses the shared product, DUT/build, method, equipment, competency, planning, results and quality backbone.</small></article><article class="card intake-workstream-card future"><div class="intake-workstream-head"><span class="status neutral">Future</span><h2>Failure Analysis</h2><p>Failure cases will accept prototype, validation, field/production or manual evidence and preserve the digital thread through investigation, root cause, corrective action and verification.</p></div><small>Uses the same genealogy, measurements, documents, resources, quality cases and learning records.</small></article></div><div class="callout"><strong>Architecture rule:</strong> these are different work types on one LabOS operating model, not three disconnected applications.</div>`;
}
