function qualityDateDelta(value){if(!value)return null;const a=new Date(P.todayISO()+'T00:00:00'),b=new Date(String(value).slice(0,10)+'T00:00:00');return Math.round((b-a)/86400000)}
function qualityInferredCause(d){const v=String(d.causeCategory||'').trim();if(v)return v;const t=String(`${d.measurement||''} ${d.step||''}`).toLowerCase();if(/material|alloy|lot|supplier/.test(t))return'Material / supplier';if(/calib|measurement|gauge|cmm|test/.test(t))return'Measurement system';if(/tool|fixture|equipment|machine/.test(t))return'Equipment / tooling';if(/operator|crimp|setup|instruction/.test(t))return'Human / competency';if(/design|dimension|requirement/.test(t))return'Design / requirement';return'Unknown / investigating'}
function qualityStageRail(d){const order=['Contain','Investigate','Disposition','Action','Verify','Close'],idx=qualityCaseStageIndex(d),closed=d.status==='CLOSED';return `<div class="quality-case-stage">${order.map((x,i)=>{const done=closed||i<idx,current=!closed&&i===idx,cls=done?'done':current?'current':'future',icon=done?'✓':current?'●':String(i+1);return `<div class="${cls}"><span>${icon}</span><strong>${x}</strong></div>`}).join('')}</div>`}
function qualityCaseCard(d){P.ensureQualityCase(d);const r=requestById(d.requestId),stage=P.qualityCaseStage(d),delta=qualityDateDelta(d.dueDate),dueText=d.status==='CLOSED'?'Closed':delta===null?'No due date':delta<0?`${Math.abs(delta)}d overdue`:delta===0?'Due today':`Due in ${delta}d`,dueClass=d.status==='CLOSED'?'good':delta!==null&&delta<0?'bad':delta!==null&&delta<=2?'warn':'neutral',openActions=(d.actions||[]).filter(a=>a.mandatory&&!a.closed),sample=d.serial?sampleDisplayFromRef(d.requestId,d.serial):'Build / batch level';return `<article class="quality-case-card ${d.releaseHold?'hold':''}"><div class="quality-case-head"><div><div class="route-toolbar"><span class="eyebrow">${esc(d.type||'Quality case')}</span>${d.releaseHold?'<span class="status bad">✕ Release hold</span>':d.status==='CLOSED'?'<span class="status good">✓ Closed</span>':'<span class="status warn">● Open</span>'}</div><h3>${esc(d.id)} · ${esc(r?.title||d.requestId)}</h3><div class="subtle">${esc(sample)} · ${esc(d.step||'General')} · Owner ${esc(d.owner||'Quality Engineer')}</div></div><div class="quality-case-due ${dueClass}"><strong>${esc(dueText)}</strong><span>${P.formatDate(d.dueDate)}</span></div></div>${qualityStageRail(d)}<div class="quality-case-focus ${d.releaseHold?'bad':'warn'}"><div><span>Current step</span><strong>${esc(stage)}</strong></div><div><span>Issue / evidence</span><strong>${esc(d.measurement||'Quality issue')}</strong></div><div><span>Cause</span><strong>${esc(qualityInferredCause(d))}</strong></div><div><span>Open actions</span><strong>${openActions.length}</strong></div></div>${d.rootCause?`<div class="quality-case-note"><strong>Root cause</strong><span>${esc(d.rootCause)}</span></div>`:''}${d.disposition&&d.disposition!=='Pending'?`<div class="quality-case-note"><strong>Disposition</strong><span>${esc(d.disposition)} · ${esc(d.justification||'justification pending')}</span></div>`:''}<div class="route-toolbar quality-case-actions">${d.status!=='CLOSED'&&can('quality:disposition')?btn(`Work ${stage} →`,`data-quality-case="${d.id}"`,'button small primary'):btn('Review case',`data-quality-case="${d.id}"`,'button small secondary')}${d.status!=='CLOSED'&&can('quality:disposition')?btn('+ Action',`data-quality-add-action="${d.id}"`,'button small secondary'):''}${btn('Open build',`data-open-request="${d.requestId}" data-tab="verify"`,'button small secondary')}</div></article>`}
function renderQualityActionBoard(){const open=(App.state.deviations||[]).filter(d=>d.status!=='CLOSED').map(P.ensureQualityCase),q=String(App.filters.qualitySearch||'').toLowerCase(),stageFilter=App.filters.qualityStage||'All',typeFilter=App.filters.qualityType||'All',only=App.filters.qualityOnly||'All';let rows=open.filter(d=>(!q||String(`${d.id} ${d.requestId} ${d.measurement} ${d.step} ${d.owner} ${d.serial}`).toLowerCase().includes(q))&&(stageFilter==='All'||P.qualityCaseStage(d)===stageFilter)&&(typeFilter==='All'||d.type===typeFilter)&&(only==='All'||only==='holds'&&d.releaseHold||only==='overdue'&&((qualityDateDelta(d.dueDate)??999)<0||(d.actions||[]).some(a=>!a.closed&&(qualityDateDelta(a.dueDate)??999)<0))));rows.sort((a,b)=>(b.releaseHold?1:0)-(a.releaseHold?1:0)||(qualityDateDelta(a.dueDate)??999)-(qualityDateDelta(b.dueDate)??999));const approvals=(App.state.approvals||[]).filter(a=>a.status!=='Approved'&&a.stage!=='report'&&(/quality/i.test(a.role||'')||a.type==='Build Readiness')),overdueActions=open.flatMap(d=>(d.actions||[]).map(a=>({d,a}))).filter(x=>!x.a.closed&&qualityDateDelta(x.a.dueDate)<0);return `<div class="quality-toolbar card">${only!=='All'?`<div class="quality-active-filter"><span class="status warn">● ${only==='holds'?'Release holds only':'Overdue cases/actions only'}</span>${btn('Clear special filter','data-quality-clear-special','button tiny secondary')}</div>`:''}<div class="quality-filter-grid"><div class="field"><label>Search cases</label><input id="qualitySearch" value="${esc(App.filters.qualitySearch||'')}" placeholder="Case, build, sample, issue..."></div><div class="field"><label>Stage</label><select id="qualityStageFilter">${['All','Contain','Investigate','Disposition','Action','Verify'].map(x=>`<option ${stageFilter===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Type</label><select id="qualityTypeFilter"><option>All</option>${[...new Set(open.map(x=>x.type).filter(Boolean))].map(x=>`<option ${typeFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div></div></div><div class="quality-action-summary"><button data-quality-tab="actions"><strong>${rows.length}</strong><span>Open cases shown</span></button><button data-quality-filter-holds><strong>${open.filter(x=>x.releaseHold).length}</strong><span>Release holds</span></button><button data-quality-tab="controlplans"><strong>${(App.state.controlPlans||[]).filter(c=>!['Approved','Superseded'].includes(c.status)).length}</strong><span>Control Plans waiting</span></button><button data-quality-overdue-actions><strong>${overdueActions.length}</strong><span>Overdue actions</span></button></div>${approvals.length?`<div class="card quality-approval-queue"><div class="section-title-row"><div><span class="eyebrow">QUALITY APPROVAL QUEUE</span><h2>${approvals.length} decision${approvals.length===1?'':'s'} waiting</h2></div></div>${approvals.slice(0,5).map(a=>`<div class="quality-approval-row"><div><strong>${esc(a.type)}</strong><span>${esc(a.requestId)} · ${esc(a.person||a.role||'Quality')}</span></div>${can('approval:perform')?btn('Review / approve',`data-approve-record="${a.id}"`,'button small primary'):status('Pending')}</div>`).join('')}</div>`:''}<div class="section-stack quality-case-list">${rows.length?rows.map(qualityCaseCard).join(''):'<div class="empty">No open quality cases match these filters.</div>'}</div>`}
function renderQualityControlPlans(){const cps=[...(App.state.controlPlans||[])].filter(c=>c.status!=='Superseded').sort((a,b)=>(a.status==='Approved')-(b.status==='Approved')||String(a.id).localeCompare(String(b.id)));return `<div class="quality-subhead"><div><span class="eyebrow">CONTROL PLAN GOVERNANCE</span><h2>Definition and approval queue</h2><p>Review the controlled characteristic, objective specification, method, sampling, reaction plan and evidence before approval.</p></div></div><div class="section-stack">${cps.map(cp=>{const chars=cp.characteristics||[],special=chars.filter(c=>c.classification),incomplete=special.filter(c=>!P.controlCharacteristicReady(c)),linked=(cp.requestIds||[]).map(requestById).filter(Boolean),ready=!incomplete.length&&chars.length>0,approvalState=controlPlanApprovalState(cp);return `<div class="card quality-cp-card"><div class="section-title-row"><div><span class="eyebrow">${esc(cp.id)} · REV ${esc(cp.revision)}</span><h3>${esc(cp.name)}</h3><div class="subtle">${esc(cp.phase||'Prototype')} · owner ${esc(cp.owner||'—')} · ${linked.length} linked build${linked.length===1?'':'s'}</div></div>${status(cp.status)}</div><div class="quality-cp-kpis"><div><strong>${chars.length}</strong><span>Controls</span></div><div><strong>${special.length}</strong><span>SC / safety</span></div><div class="${incomplete.length?'bad-text':''}"><strong>${incomplete.length}</strong><span>Incomplete</span></div></div>${incomplete.length?`<div class="callout bad"><strong>Approval blocker:</strong> ${esc(incomplete.map(x=>x.characteristic).join(', '))} still need objective specification / method / reaction / evidence.</div>`:cp.status!=='Approved'?'<div class="callout warn"><strong>Definition complete.</strong> Independent review / approval can proceed.</div>':''}<div class="route-toolbar">${can('controlplan:edit')?btn(cp.status==='Approved'?'Revise Control Plan':'Edit Control Plan',`data-edit-control-plan="${cp.id}"`,'button small secondary'):''}${cp.status!=='Approved'&&ready?(approvalState.stage==='submit-review'?(can('controlplan:edit')||currentRole()==='administrator'?btn('Submit for independent review',`data-request-cp-review="${cp.id}"`,'button small primary'):btn('Awaiting review request','data-quality-tab="controlplans"','button small secondary')):approvalState.canApprove?btn('Approve formally',`data-approve-cp="${cp.id}"`,'button small primary'):approvalState.switchRole?btn(`Switch to ${esc(approvalState.switchName||roleLabel(approvalState.switchRole))}`,`data-switch-role="${approvalState.switchRole}"`,'button small primary'):''):''}${linked[0]?btn('Open linked build',`data-open-request="${linked[0].id}" data-tab="controls"`,'button small secondary'):''}</div></div>`}).join('')}</div>`}
function renderQualityRisks(){return renderQualityControlPlans()}
function renderQualityTrends(){const all=(App.state.deviations||[]).map(P.ensureQualityCase),cause={};all.forEach(d=>{const k=qualityInferredCause(d);cause[k]=(cause[k]||0)+1});const pareto=Object.entries(cause).sort((a,b)=>b[1]-a[1]),mx=Math.max(1,...pareto.map(x=>x[1])),hist=App.state.buildHistory||[],fpy=hist.length?hist.reduce((n,h)=>n+Number(h.firstPassYield||0),0)/hist.length*100:null,scrap=hist.length?hist.reduce((n,h)=>n+Number(h.scrapRate||0),0)/hist.length*100:null,closed=all.filter(d=>d.status==='CLOSED').length,verified=all.filter(d=>d.status==='CLOSED'&&d.effectiveness==='Verified').length,proposals=(App.state.improvementProposals||[]).filter(x=>x.type==='Quality'||/quality/i.test(x.title||''));return `<div class="quality-action-summary"><button><strong>${fpy===null?'—':fpy.toFixed(1)+'%'}</strong><span>Historical FPY</span></button><button><strong>${scrap===null?'—':scrap.toFixed(1)+'%'}</strong><span>Historical scrap</span></button><button><strong>${closed?Math.round(verified/closed*100)+'%':'—'}</strong><span>Closed cases verified</span></button><button><strong>${proposals.length}</strong><span>Quality improvements</span></button></div><div class="grid cols-2 quality-trend-grid"><div class="card"><span class="eyebrow">ROOT-CAUSE PARETO</span><h2>Where quality loss originates</h2><div class="quality-pareto">${pareto.length?pareto.map(([k,n],i)=>`<div><span class="rank">${i+1}</span><strong>${esc(k)}</strong><div class="util-meter"><i style="width:${Math.round(n/mx*100)}%"></i></div><b>${n}</b></div>`).join(''):'<div class="empty">No quality-case history yet.</div>'}</div></div><div class="card"><span class="eyebrow">CONTINUOUS IMPROVEMENT</span><h2>Evidence that should change the system</h2>${proposals.length?proposals.slice(0,8).map(p=>`<div class="quality-improvement-row"><div><strong>${esc(p.title)}</strong><span>${esc(p.why||p.impact||'Quality signal')}</span></div>${btn('Review',`data-improvement="${p.id}"`,'button tiny secondary')}</div>`).join(''):'<div class="empty">Run the Daily Operations Check to generate evidence-based improvement proposals.</div>'}</div></div>`}
function renderQualityHistory(){const closed=(App.state.deviations||[]).filter(d=>d.status==='CLOSED').map(P.ensureQualityCase).sort((a,b)=>String(b.verifiedAt||b.detectedAt||'').localeCompare(String(a.verifiedAt||a.detectedAt||'')));return `<div class="quality-subhead"><div><span class="eyebrow">CLOSED QUALITY RECORDS</span><h2>Verified case history</h2><p>Closed cases remain connected to the build, physical sample, disposition, actions and effectiveness evidence.</p></div></div><div class="section-stack quality-case-list">${closed.length?closed.map(qualityCaseCard).join(''):'<div class="empty">No closed quality cases yet.</div>'}</div>`}
function renderQuality(){const open=(App.state.deviations||[]).filter(d=>d.status!=='CLOSED').map(P.ensureQualityCase),holds=open.filter(d=>d.releaseHold),pendingCp=(App.state.controlPlans||[]).filter(c=>!['Approved','Superseded'].includes(c.status)),tab=['actions','controlplans','capability','trends','history'].includes(App.filters.qualityTab)?App.filters.qualityTab:'actions',tabs=[['actions','Action board',open.length],['controlplans','Control Plans',pendingCp.length],['capability','Capability & SPC',''],['trends','Trends & improvement',''],['history','Case history',(App.state.deviations||[]).filter(d=>d.status==='CLOSED').length]];const body=tab==='controlplans'?renderQualityControlPlans():tab==='capability'?renderCharacterisation(true):tab==='trends'?renderQualityTrends():tab==='history'?renderQualityHistory():renderQualityActionBoard();return pageHeader('Quality','Control Plans, capability/SPC, nonconformance and verified quality learning on one shared layer.',can('quality:disposition')?btn('+ New quality case','data-quality-new','button primary'):'')+`<div class="quality-command-strip"><div class="quality-command red"><span>✕</span><div><strong>${holds.length}</strong><small>Release holds</small></div></div><div class="quality-command yellow"><span>●</span><div><strong>${open.length}</strong><small>Open quality cases</small></div></div><div class="quality-command yellow"><span>●</span><div><strong>${pendingCp.length}</strong><small>Control Plans awaiting decision</small></div></div></div><div class="quality-tabs">${tabs.map(([id,label,count])=>`<button class="${tab===id?'active':''}" data-quality-tab="${id}">${esc(label)}${count!==''?` <b>${count}</b>`:''}</button>`).join('')}</div>${body}`}
function renderReports(){const q=String(App.filters.reportSearch||'').toLowerCase(),scope=App.filters.reportScope||'All',rows=(App.state.requests||[]).filter(r=>(scope==='All'||scope==='Archived'&&(r.archived||r.status==='CLOSED')||scope==='Active'&&!(r.archived||r.status==='CLOSED'))&&(!q||`${r.id} ${r.title} ${r.productFamily} ${r.programme} ${r.owner}`.toLowerCase().includes(q))).sort((a,b)=>String(b.actualDeliveryDate||b.requiredDate||'').localeCompare(String(a.actualDeliveryDate||a.requiredDate||'')));return pageHeader('Build Reports','Controlled build dossiers with route, Control Plan, results, capability, genealogy, quality exceptions and approvals.')+`<div class="card"><div class="report-search-controls"><label>Search<input id="reportSearch" value="${esc(App.filters.reportSearch||'')}" placeholder="Build, product, project, owner…"></label><label>Status<select id="reportScope">${['All','Active','Archived'].map(x=>`<option ${scope===x?'selected':''}>${x}</option>`).join('')}</select></label></div></div><div class="card"><div class="section-title-row"><div><h2>Controlled build dossiers</h2></div><span class="pill">${rows.length} build(s)</span></div><div class="request-card-grid">${rows.map(r=>{const a=P.ensureBuildReportApproval(App.state,r),final=a.status==='Approved',archived=!!(r.archived||r.status==='CLOSED');return `<article class="request-search-card ${final?'good':archived?'archive':'warn'}"><div class="request-card-main"><span class="request-card-state">${final?'✓':'●'}</span><div><span class="request-mobile-id">${esc(r.id)}</span><strong>${esc(r.title)}</strong><small>${esc(r.productFamily)} · ${esc(r.programme||'No project')}</small></div><div class="request-card-date"><b>${final?'FINAL':'DRAFT'}</b><small>Rev ${esc(r.buildReportRevision||'A')}</small></div></div><div class="request-card-meta"><span>Owner <b>${esc(r.owner||'Unassigned')}</b></span><span>Approver <b>${esc(a.person||'—')}</b></span><span>Delivery <b>${P.formatDate(r.actualDeliveryDate||r.requiredDate)}</b></span></div><div class="request-card-actions">${btn('Open Build Report',`data-report="${r.id}"`,'button tiny primary')}${btn('Route traveller',`data-route-sheet="${r.id}"`,'button tiny secondary')}${btn('Open build',`data-open-request="${r.id}"`,'button tiny secondary')}</div></article>`}).join('')||'<div class="empty">No builds match the report filters.</div>'}</div></div>`}
function renderHelp(){const tasks=[['How engineering requests a prototype',['Open Requests → Prototype and choose New prototype request.','Complete the six guided steps: need, objective, date/priority, configuration, characterisation, review.','Submit only after the review confirms required data.','Track Requested Date, Current Forecast, Readiness, Risk, Owner and Next Action in the workspace.']],['How lab triages a request',['Open the request workspace.','Review objective, configuration, required date and requested characterisation.','First assess exact material supply/arrival and confirm the actual process + requested test methods. Only then run AUTO-PLAN to create visible equipment/person bookings and a forecast.','Commit the forecast and continue once the timing basis is acceptable; resolve Action Centre items instead of creating detached notes.']],['How to issue the correct build material',['Tap Material source & feasibility.','Review the required part number, revision and quantity for each BOM line.','For Lab supplied, reserve only exact matching part/revision lots; for Engineering supplied, record expected arrival and then receive the actual lot. Issue is required before build start.','Legacy allocations that are not linked to a current BOM requirement remain visible for audit history but do not satisfy readiness.']],['How to select a standard process',['In the guided checklist, tap Process route & test-method assessment.','Insert a released library process.','Use process fit assessment for capability/material/geometry fit.','If outside the released envelope, start modified/new process development.']],['How to develop a new process',['Open Process Library or tap Process route & test-method assessment in the guided checklist.','Create a development workflow: plan → trials → parameters → risk → measurement/capability → Control Plan → work instruction → approval → release.','Compare trials and retain observations/evidence.','Release only when required gates are satisfied.']],['How to create/review a Control Plan',['Open the guided checklist and tap Control Plan, risk controls & special approvals.','Link controls to process steps and characteristics.','Ensure every special characteristic has an objective target and/or limits, method/gauge, evidence and reaction plan.','Request independent review; approved plans are revised rather than silently edited.']],['How to perform build-readiness review',['In the guided checklist, tap Build readiness.','Review each large readiness line.','For a blocker, read what/why/who/action/evidence/then.','Use controlled override only with authorised role and recorded reason/risk.']],['How a technician executes a build',['Switch to Prototype Technician.','In the guided checklist, tap Build samples & capture process evidence.','Create the sample register to the requested quantity. The Lab Sample ID is permanent; the sample number is the editable working label; a formal serial is separate.','For each route operation, select the sample (or batch), then select only equipment capable of that operation and record the process evidence. Equipment is linked to the execution record, not permanently to the sample.','Where a Control Plan characteristic belongs to that process step, record the result there before continuing.']],['How to record characterisation',['In the guided checklist, tap Characterise, evaluate & disposition exceptions.','Use manual entry or CSV import.','End-characterisation uses a sample × test matrix. Results retain raw values, units, limits, Lab Sample ID/sample number/formal serial, method, equipment/calibration certificate, operator and timestamp.','Out-of-limit results create/maintain a quality hold until disposed.']],['How to manage a deviation/rework',['In the guided checklist, tap Characterise, evaluate & disposition exceptions.','Contain, investigate and choose an authorised disposition.','For rework, route back to the controlled process and reinspection step.','Close only when mandatory actions and verification are complete.']],['How to sign off/release a build',['Follow the guided checklist through Characterise, evaluate & disposition exceptions and Release approval.','Confirm serial counts, configuration, deviations, characterisation and special-characteristic status.','Release only when required approvals and release-hold checks pass.','Then use Deliver, retain records & close.']],['How to find a sample / serial history',['Use global search or Sample & Serial History.','Open the sample to see its working sample number, permanent Lab Sample ID, optional/required formal serial, material lots, process revisions, CP/end-characterisation measurements, quality issues and delivery.']],['How to manage calibration, maintenance & training',['Open Resource Assurance.','Choose Calibration, Maintenance or Training; filter overdue/upcoming work and group equipment by device/type/capability or training by person/competency.','Select the items you want to plan and choose Review & schedule selected. LabOS shows a lowest-impact suggestion based on committed and probability-weighted demand.','Choose the suggested slot or another resolvable time. If the slot overlaps build work, LabOS automatically replans the affected builds before saving; fixed readiness/lab collisions are rejected. AUTO-PLAN can also reserve required calibration, maintenance or training as a prerequisite when it can resolve the full plan.','Complete the real activity through calibration certificates, maintenance records or competency certificates.']],['How to generate a prototype report',['Open Build Reports globally or use Deliver, retain records & close for request records.','LabOS generates one Build Report containing process/work instructions, Control Plan, tests/characterisation, critical-characteristic capability, data, photos, genealogy and quality evidence. External risk analysis remains in its controlled source system; applicable characteristics and controls are flowed into the LabOS Control Plan.','Drafts remain NOT APPROVED until the designated report approver signs the current revision.','Use print/save-PDF from the browser for a portable controlled copy.']]];
 return pageHeader('Help / User Manual','Task-based guidance for the actual proof-of-concept application.')+`<div class="card"><h2>Quick Start</h2><div class="quick-start"><div class="quick-step"><strong>1 · Pick a role</strong><span>Use Demo role at the top right.</span></div><div class="quick-step"><strong>2 · Open a scenario</strong><span>Prototype includes 15 seeded automotive examples.</span></div><div class="quick-step"><strong>3 · Follow Next Action</strong><span>Each workspace explains blockers and direct resolution paths.</span></div><div class="quick-step"><strong>4 · Test controls</strong><span>Try AUTO-PLAN, readiness, execution, quality and report flows.</span></div></div></div><div style="height:14px"></div>${tasks.map(([t,steps])=>`<details class="help-task"><summary>${esc(t)}</summary><div class="help-body"><ol>${steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div></details>`).join('')}`
}
function axisLineChart(rows,series,{title='',yLabel='',suffix='',prefix='',min=null,max=null}={}){const keys=series.map(x=>x.key),vals=rows.flatMap(r=>keys.map(k=>Number(r[k])).filter(Number.isFinite));if(!vals.length)return '<div class="empty compact">No data in the selected period.</div>';let lo=min!==null?min:Math.min(...vals),hi=max!==null?max:Math.max(...vals);if(lo===hi){lo=Math.max(0,lo-1);hi+=1}const W=760,H=250,pL=64,pR=20,pT=18,pB=44,pW=W-pL-pR,pH=H-pT-pB,span=hi-lo,x=i=>pL+i*(pW/Math.max(1,rows.length-1)),y=v=>pT+pH-(v-lo)/span*pH,ticks=Array.from({length:5},(_,i)=>lo+(hi-lo)*i/4);const paths=series.map((sr,si)=>{const pts=rows.map((r,i)=>Number.isFinite(Number(r[sr.key]))?{x:x(i),y:y(Number(r[sr.key])),v:Number(r[sr.key]),label:r.label}:null).filter(Boolean);return `<path d="${pts.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ')}" class="kpi-line series-${si}"/>${pts.map(p=>`<circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="3.5" class="kpi-dot series-${si}"><title>${esc(sr.label||sr.key)} · ${esc(p.label)}: ${prefix}${p.v.toFixed(1)}${suffix}</title></circle>`).join('')}`}).join('');return `<div class="kpi-chart-legend">${series.map((sr,i)=>`<span><i class="series-${i}"></i>${esc(sr.label||sr.key)}</span>`).join('')}</div><svg class="kpi-line-chart axis-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(title)}">${ticks.map(t=>`<line x1="${pL}" y1="${y(t)}" x2="${W-pR}" y2="${y(t)}" class="kpi-grid"/><text x="${pL-8}" y="${y(t)+4}" text-anchor="end">${prefix}${t.toFixed(suffix==='%'?0:1)}${suffix}</text>`).join('')}<line x1="${pL}" y1="${pT+pH}" x2="${W-pR}" y2="${pT+pH}" class="kpi-axis"/>${paths}${rows.map((r,i)=>`<text x="${x(i)}" y="${H-16}" text-anchor="middle">${esc(r.label)}</text>`).join('')}<text class="kpi-axis-label" transform="translate(15 ${pT+pH/2}) rotate(-90)" text-anchor="middle">${esc(yLabel)}</text></svg>`}

function capacityOutlookChart(forward,weeks=13){const n=Math.min(weeks,forward.weeks.length),rows=forward.weeks.slice(0,n).map((w,i)=>{const eq=Math.max(0,...Object.values(forward.equipment||{}).map(x=>pct(Number(x.committed?.[i]||0)+Number(x.pipeline?.[i]||0),Number(x.capacity||0)))),sk=Math.max(0,...Object.values(forward.skills||{}).map(x=>pct(Number(x.committed?.[i]||0)+Number(x.pipeline?.[i]||0),Number(x.capacity||0))));return {label:w.label,eq,sk}}),max=Math.max(110,...rows.flatMap(x=>[x.eq,x.sk])),W=760,H=230,pL=42,pR=18,pT=20,pB=40,pW=W-pL-pR,pH=H-pT-pB,y=v=>pT+pH-v/max*pH,x=i=>pL+i*(pW/Math.max(1,rows.length-1)),path=k=>rows.map((r,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(r[k]).toFixed(1)}`).join(' '),capY=y(100);return `<div class="kpi-chart-legend"><span><i class="eq"></i>Equipment peak</span><span><i class="skill"></i>Certified-skill peak</span><span><i class="limit"></i>100% capacity</span></div><svg class="kpi-line-chart" viewBox="0 0 ${W} ${H}"><line x1="${pL}" y1="${capY}" x2="${W-pR}" y2="${capY}" class="kpi-limit"/><path d="${path('eq')}" class="kpi-line eq"/><path d="${path('sk')}" class="kpi-line skill"/>${rows.map((r,i)=>i%Math.max(1,Math.ceil(rows.length/7))===0||i===rows.length-1?`<text x="${x(i)}" y="${H-14}" text-anchor="middle">${esc(r.label)}</text>`:'').join('')}</svg>`}

function forwardBuckets(forward,spec){const weeks=forward.weeks||[],weekRows=weeks.map((w,i)=>{const eq=Math.max(0,...Object.values(forward.equipment||{}).map(x=>pct(Number(x.committed?.[i]||0)+Number(x.pipeline?.[i]||0),Number(x.capacity||0)))),sk=Math.max(0,...Object.values(forward.skills||{}).map(x=>pct(Number(x.committed?.[i]||0)+Number(x.pipeline?.[i]||0),Number(x.capacity||0)))),pipe=Object.values(forward.equipment||{}).reduce((n,x)=>n+Number(x.pipeline?.[i]||0),0);return{date:new Date(w.start||Date.now()+i*7*86400000),eq,sk,pipe}});const out=[],group=(items,label)=>out.push({label,eq:items.length?Math.max(...items.map(x=>x.eq)):0,sk:items.length?Math.max(...items.map(x=>x.sk)):0,pipe:items.reduce((n,x)=>n+x.pipe,0)});
 if(spec.single==='week'){const st=isoWeekStart(spec.focus),base=weekRows[0]||{eq:0,sk:0,pipe:0};for(let i=0;i<7;i++){const d=planAddDays(st,i);out.push({label:d.toLocaleDateString(undefined,{weekday:'short',day:'numeric'}),eq:base.eq,sk:base.sk,pipe:base.pipe/7})}return out}
 if(spec.single==='month'){for(let i=0;i<spec.count;i++){const x=weekRows[i]||{eq:0,sk:0,pipe:0};out.push({label:`W${i+1}`,eq:x.eq,sk:x.sk,pipe:x.pipe})}return out}
 if(spec.mode==='week')weekRows.slice(0,spec.count).forEach(x=>group([x],x.date.toLocaleDateString(undefined,{day:'numeric',month:'short'})));
 else if(spec.mode==='month'){for(let i=0;i<spec.count;i++){const d=new Date();d.setMonth(d.getMonth()+i);const items=weekRows.filter(x=>x.date.getFullYear()===d.getFullYear()&&x.date.getMonth()===d.getMonth());group(items,d.toLocaleDateString(undefined,{month:'short',year:'2-digit'}))}}
 else if(spec.mode==='quarter'){for(let i=0;i<spec.count;i++){const d=new Date();d.setMonth(d.getMonth()+i*3);const q=Math.floor(d.getMonth()/3),items=weekRows.filter(x=>x.date.getFullYear()===d.getFullYear()&&Math.floor(x.date.getMonth()/3)===q);group(items,`Q${q+1} ${String(d.getFullYear()).slice(-2)}`)}}
 else weekRows.slice(0,spec.count).forEach(x=>group([x],x.date.toLocaleDateString(undefined,{day:'numeric',month:'short'})));return out}

function futureProjectImpact(id){const project=(App.state.pipelineProjects||[]).find(x=>x.id===id);if(!project)return null;const spec=kpiPeriodSpec(),weeks=spec.mode==='quarter'?104:spec.mode==='month'?52:26,baseState=P.deepClone(App.state);baseState.pipelineProjects=(baseState.pipelineProjects||[]).filter(x=>x.id!==id);const weightedState=P.deepClone(baseState);weightedState.pipelineProjects.push(P.deepClone(project));const fullState=P.deepClone(baseState),full=P.deepClone(project);full.probability=1;fullState.pipelineProjects.push(full);const svc=new P.ForwardDemandService(),base=svc.build(baseState,{product:'all',weeks}),weighted=svc.build(weightedState,{product:'all',weeks}),fullF=svc.build(fullState,{product:'all',weeks}),peak=f=>Math.max(capacityState(f).eqPeak,capacityState(f).skPeak),resources=[];for(const [k,x] of Object.entries(weighted.equipment||{})){const b=base.equipment?.[k],delta=(x.pipeline||[]).reduce((n,v,i)=>n+Math.max(0,Number(v||0)-Number(b?.pipeline?.[i]||0)),0);if(delta>0)resources.push({type:'Equipment',label:k,hours:delta})}for(const [k,x] of Object.entries(weighted.skills||{})){const b=base.skills?.[k],delta=(x.pipeline||[]).reduce((n,v,i)=>n+Math.max(0,Number(v||0)-Number(b?.pipeline?.[i]||0)),0);if(delta>0)resources.push({type:'Skill',label:x.label||k,hours:delta})}resources.sort((a,b)=>b.hours-a.hours);return{project,basePeak:peak(base),weightedPeak:peak(weighted),fullPeak:peak(fullF),weightedDelta:peak(weighted)-peak(base),fullDelta:peak(fullF)-peak(base),weightedHours:resources.filter(x=>x.type==='Equipment').reduce((n,x)=>n+x.hours,0),resources}}

function guidedDetailLead(r,steps){const step=selectedGuidedStep(steps);if(!step)return '';return `<div class="guide-detail-head stable-detail-head"><div><span class="eyebrow">STEP ${step.index} · ${esc(step.phase)}</span><h2>${esc(step.title)}</h2><p><b>Owner:</b> ${esc(step.owner)}<br><b>${step.done?'Evidence':'Next action'}:</b> ${esc(step.next)}</p></div></div>`}

function guidedOverviewPanel(r,steps){const current=steps.find(s=>['current','blocked'].includes(s.state))||steps[steps.length-1];const rs=new P.ReadinessService(App.state).evaluate(r.id);const action=current?.direct==='submit'&&can('request:create')?btn('Submit request →',`data-submit-request="${r.id}"`,'button primary'):btn(`Open ${current?.title||'next step'} →`,`data-workspace-tab="${current?.id||'configuration'}"`,'button primary');return `<div class="card guided-focus"><span class="eyebrow">NEXT ACTION</span><h2>${esc(current?.title||'Workflow complete')}</h2><p>${esc(current?.next||'All guided steps are complete.')}</p><div class="guided-focus-meta"><span><b>Owner</b>${esc(current?.owner||r.owner)}</span><span><b>Current gate</b>${esc(r.currentGate)}</span><span><b>Readiness</b>${rs.ready?'Ready':`${rs.issues.length} blocker${rs.issues.length===1?'':'s'}`}</span></div><div class="guided-focus-action">${action}</div></div>`}

function isoWeekStart(isoWeek){const [y,w]=String(isoWeek||'').split('-W').map(Number);const jan4=new Date(y,0,4),monday=new Date(jan4);monday.setDate(jan4.getDate()-((jan4.getDay()+6)%7)+(w-1)*7);monday.setHours(0,0,0,0);return monday}

function kpiBottleneckVisual(forward){const rows=[];for(const [k,x] of Object.entries(forward.equipment||{})){const peak=Math.max(...x.committed.map((v,i)=>Number(v||0)+Number(x.pipeline[i]||0)),0),cap=Number(x.capacity||0);rows.push({label:k,type:'Equipment',peak,cap,u:cap?100*peak/cap:peak?999:0})}for(const [k,x] of Object.entries(forward.skills||{})){const peak=Math.max(...x.committed.map((v,i)=>Number(v||0)+Number(x.pipeline[i]||0)),0),cap=Number(x.capacity||0);rows.push({label:x.label||k,type:'Skill',peak,cap,u:cap?100*peak/cap:peak?999:0})}rows.sort((a,b)=>b.u-a.u);return `<div class="bottleneck-rank">${rows.slice(0,10).map((x,i)=>`<div class="bottleneck-row"><span class="rank">${i+1}</span><div><strong>${esc(x.label)}</strong><small>${esc(x.type)} · peak ${x.peak.toFixed(1)} / ${x.cap.toFixed(1)} h/wk</small></div><div class="util-meter"><i style="width:${Math.min(100,x.u)}%"></i></div><b class="${x.u>100?'bad-text':x.u>85?'warn-text':''}">${x.u.toFixed(0)}%</b></div>`).join('')}</div>`}

function kpiHeatmap(forward,weeks=13){const series=[...Object.entries(forward.equipment||{}).map(([k,x])=>({label:k,x})),...Object.entries(forward.skills||{}).map(([k,x])=>({label:x.label||k,x}))].map(o=>({...o,peak:Math.max(...o.x.committed.slice(0,weeks).map((v,i)=>{const cap=Number(o.x.capacity||0);return cap?100*(Number(v||0)+Number(o.x.pipeline[i]||0))/cap:0}),0)})).sort((a,b)=>b.peak-a.peak).slice(0,8);return `<div class="capacity-heatmap"><div class="heat-head"><span>Resource</span>${forward.weeks.slice(0,weeks).map(w=>`<small>${esc(w.label||String(w.start).slice(5))}</small>`).join('')}</div>${series.map(o=>`<div class="heat-row"><strong>${esc(o.label)}</strong>${o.x.committed.slice(0,weeks).map((v,i)=>{const cap=Number(o.x.capacity||0),u=cap?100*(Number(v||0)+Number(o.x.pipeline[i]||0))/cap:0,lev=u>100?4:u>85?3:u>60?2:u>30?1:0;return `<span class="heat l${lev}" title="${u.toFixed(0)}%">${u.toFixed(0)}</span>`}).join('')}</div>`).join('')}</div>`}

function kpiHistoryBuckets(hist,spec){const now=new Date(),b=[];const add=(start,end,label)=>{const h=hist.filter(x=>{const d=new Date(x.completedAt);return d>=start&&d<end}),qty=h.reduce((n,x)=>n+Number(x.quantity||0),0),actual=h.reduce((n,x)=>n+Number(x.actualCost||0),0),copq=h.reduce((n,x)=>n+Number(x.costOfPoorQuality||0),0);b.push({label,start,end,n:h.length,fpy:h.length?100*h.reduce((n,x)=>n+Number(x.firstPassYield||0),0)/h.length:null,cost:qty?actual/qty:null,rework:h.length?h.reduce((n,x)=>n+Number(x.reworkHours||0),0)/h.length:null,scrap:h.length?100*h.reduce((n,x)=>n+Number(x.scrapRate||0),0)/h.length:null,copq:actual?100*copq/actual:null})};
 if(spec.single==='week'){const st=isoWeekStart(spec.focus);for(let i=0;i<7;i++){const s=planAddDays(st,i),e=planAddDays(s,1);add(s,e,s.toLocaleDateString(undefined,{weekday:'short',day:'numeric'}))}return b}
 if(spec.single==='month'){const [y,m]=spec.focus.split('-').map(Number),monthStart=new Date(y,m-1,1),monthEnd=new Date(y,m,1);let st=planWeekStart(monthStart);for(let i=0;i<6&&st<monthEnd;i++){const en=planAddDays(st,7),s=st<monthStart?monthStart:st,e=en>monthEnd?monthEnd:en;add(s,e,`W${i+1}`);st=en}return b}
 if(spec.mode==='week'){const thisWeek=planWeekStart(now);for(let i=spec.count-1;i>=0;i--){const st=planAddDays(thisWeek,-7*i),en=planAddDays(st,7);add(st,en,st.toLocaleDateString(undefined,{day:'numeric',month:'short'}))}}
 else if(spec.mode==='month'){for(let i=spec.count-1;i>=0;i--){const st=new Date(now.getFullYear(),now.getMonth()-i,1),en=new Date(now.getFullYear(),now.getMonth()-i+1,1);add(st,en,st.toLocaleDateString(undefined,{month:'short',year:'2-digit'}))}}
 else if(spec.mode==='quarter'){const q=Math.floor(now.getMonth()/3);for(let i=spec.count-1;i>=0;i--){const qidx=q-i,y=now.getFullYear()+Math.floor(qidx/4),qq=((qidx%4)+4)%4,st=new Date(y,qq*3,1),en=new Date(y,qq*3+3,1);add(st,en,`Q${qq+1} ${String(y).slice(-2)}`)}}return b}

function kpiPeriodSpec(){const mode=App.filters.kpiTimeBasis||'week13',now=new Date();if(mode==='month12')return{mode:'month',count:12,label:'Monthly · last / next 12 months'};if(mode==='quarter8')return{mode:'quarter',count:8,label:'Quarterly · last / next 8 quarters'};if(mode==='singleWeek'){const value=App.filters.kpiFocusWeek||`${now.getFullYear()}-W${String(Math.ceil((((now-new Date(now.getFullYear(),0,1))/86400000)+new Date(now.getFullYear(),0,1).getDay()+1)/7)).padStart(2,'0')}`;return{mode:'day',count:7,label:'Selected week',focus:value,single:'week'}}if(mode==='singleMonth'){const value=App.filters.kpiFocusMonth||`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;return{mode:'monthWeek',count:5,label:'Selected month',focus:value,single:'month'}}return{mode:'week',count:13,label:'Weekly · last / next 13 weeks'}}

function monthBuckets(hist,months=6){const now=new Date(),out=[];for(let i=months-1;i>=0;i--){const start=new Date(now.getFullYear(),now.getMonth()-i,1),end=new Date(now.getFullYear(),now.getMonth()-i+1,1),h=hist.filter(x=>{const d=new Date(x.completedAt);return d>=start&&d<end});const qty=h.reduce((n,x)=>n+Number(x.quantity||0),0),actual=h.reduce((n,x)=>n+Number(x.actualCost||0),0),copq=h.reduce((n,x)=>n+Number(x.costOfPoorQuality||0),0);out.push({label:start.toLocaleDateString(undefined,{month:'short'}),fpy:h.length?100*h.reduce((n,x)=>n+Number(x.firstPassYield||0),0)/h.length:null,cost:qty?actual/qty:null,copq:actual?100*copq/actual:null,n:h.length})}return out}

function processPerformanceTable(hist){const rows=[];for(const p of App.state.processes||[]){const evidence=[];for(const h of hist){for(const x of (h.stepActuals||[]).filter(x=>x.processId===p.id)){const actual=Number(x.durationHours),qty=Math.max(1,Number(h.quantity||1));if(Number.isFinite(actual))evidence.push({actual,standard:P.planningStandardHours(p,qty),qty})}}if(!evidence.length)continue;const med=P.median(evidence.map(x=>x.actual)),std=P.median(evidence.map(x=>x.standard)),ratios=evidence.filter(x=>x.standard>0).map(x=>100*(x.actual-x.standard)/x.standard),delta=P.median(ratios)||0;rows.push({p,med,std,delta,n:evidence.length,minQty:Math.min(...evidence.map(x=>x.qty)),maxQty:Math.max(...evidence.map(x=>x.qty))})}rows.sort((a,b)=>b.delta-a.delta);const canEdit=currentRole()==='lab_manager'||currentRole()==='administrator';return rows.length?`<div class="callout"><strong>How these times are built</strong><p><b>Historical actual</b> is measured from timestamped process execution (Start → Complete) and retained when a build is closed. <b>Released standard</b> is Lab Manager master data: setup time + cycle time × the quantity of each historical build (or one cycle for Batch basis). The variance is therefore compared at the same historical quantities.</p></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Process</th><th>Historical median actual</th><th>Median released standard @ same qty</th><th>Variance</th><th>Evidence builds</th><th></th></tr></thead><tbody>${rows.slice(0,10).map(x=>`<tr><td><strong>${esc(x.p.name)}</strong><br><small>${esc(x.p.id)} · ${esc(x.p.basis||'Unit')} basis · ${esc(x.p.setupTime||0)} min setup + ${esc(x.p.cycleTime||0)} min cycle</small></td><td>${x.med.toFixed(1)} h</td><td>${x.std.toFixed(1)} h</td><td class="${x.delta>20?'bad-text':x.delta>10?'warn-text':'good-text'}">${x.delta>=0?'+':''}${x.delta.toFixed(0)}%</td><td>${x.n}<br><small>qty ${x.minQty}${x.maxQty!==x.minQty?'–'+x.maxQty:''}</small></td><td>${canEdit?btn('Edit standard',`data-edit-process-standard="${x.p.id}"`,'button tiny secondary'):''}</td></tr>`).join('')}</tbody></table></div><div class="subtle" style="margin-top:8px">Demo history is seeded example data. Real builds replace/add evidence automatically when technicians use Start/Complete during execution and the build is closed.</div>`:'<div class="empty compact">No process actuals in the selected period.</div>'}

function quarterSummary(seriesMap,weeks){const qOrder=[];weeks.forEach(w=>{if(!qOrder.includes(w.quarter))qOrder.push(w.quarter)});const qWeekCounts=Object.fromEntries(qOrder.map(q=>[q,weeks.filter(w=>w.quarter===q).length]));const rows=Object.values(seriesMap).map(s=>{const qs=qOrder.map(q=>{let h=0,peak=0;weeks.forEach((w,i)=>{if(w.quarter!==q)return;const v=Number(s.committed[i]||0)+Number(s.pipeline[i]||0);h+=v;peak=Math.max(peak,v)});const capacity=Number(s.capacity||0)*qWeekCounts[q],util=pct(h,capacity);return {h,peak,capacity,util}});return {label:s.label,capacity:s.capacity,qs}}).sort((a,b)=>(b.qs[0]?.util||0)-(a.qs[0]?.util||0)).slice(0,10);return `<div class="table-wrap"><table class="data-table forward-summary"><thead><tr><th>Resource</th>${qOrder.map(q=>`<th>${esc(q)} demand / capacity</th>`).join('')}<th>Peak week / weekly cap</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.label)}</strong><br><small>${Number(r.capacity||0).toFixed(0)} h/week current capacity</small></td>${r.qs.map(q=>`<td><strong>${q.util.toFixed(0)}%</strong><br><small>${q.h.toFixed(1)} / ${q.capacity.toFixed(0)} h</small></td>`).join('')}<td>${Math.max(...r.qs.map(q=>q.peak),0).toFixed(1)} / ${Number(r.capacity||0).toFixed(0)} h</td></tr>`).join('')||'<tr><td colspan="4">No forecast demand.</td></tr>'}</tbody></table></div>`}

function replanReasonBars(requests){const counts={};for(const r of requests)for(const x of r.commitmentHistory||[])if(x.type==='replan')counts[x.reasonCategory||'Other']=(counts[x.reasonCategory||'Other']||0)+1;const rows=Object.entries(counts).sort((a,b)=>b[1]-a[1]);if(!rows.length)return '<div class="empty compact">No accepted replans in this selection.</div>';const max=Math.max(...rows.map(x=>x[1]));return `<div class="issue-bars">${rows.map(([label,count])=>`<div class="issue-row"><strong>${esc(label)}</strong><div><span style="width:${100*count/max}%"></span></div><b>${count}</b></div>`).join('')}</div>`}
function commitmentPerformanceTable(requests){const rows=requests.filter(r=>r.originalCommitmentDate).slice().sort((a,b)=>String(b.actualDeliveryDate||b.requiredDate).localeCompare(String(a.actualDeliveryDate||a.requiredDate))).slice(0,20);return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Build</th><th>Original</th><th>Current/final</th><th>Replans</th><th>Net movement</th><th>Actual</th><th>Actual vs original</th></tr></thead><tbody>${rows.map(r=>{const m=P.commitmentMetrics(r);return `<tr><td><button class="table-link" data-open-request="${r.id}" data-tab="schedule">${esc(r.id)}</button><br><small>${esc(r.productFamily)}</small></td><td>${P.formatDate(m.original)}</td><td>${P.formatDate(m.current)}</td><td>${m.replanCount}</td><td>${m.netReplanDays>0?'+':''}${m.netReplanDays} d</td><td>${P.formatDate(m.actual)}</td><td>${m.actualVsOriginalDays===null?'—':`${m.actualVsOriginalDays>0?'+':''}${m.actualVsOriginalDays} d`}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty compact">No committed builds in this selection.</div>'}
