function readinessActionTarget(name){
 const n=String(name||'').toLowerCase();
 if(n.includes('material'))return {tab:'materials',label:'Resolve material readiness'};
 if(n.includes('timing')||n.includes('commit'))return {tab:'schedule',label:'Resolve resource timing'};
 if(n.includes('route')||n.includes('process')||n.includes('test method')||n.includes('risk'))return {tab:'processrisk',label:'Resolve process / risk definition'};
 if(n.includes('control plan')||n.includes('characteristic')||n.includes('product safety'))return {tab:'controls',label:'Resolve controls / approvals'};
 if(n.includes('equipment'))return {nav:'equipment-master',label:'Resolve equipment blocker'};
 if(n.includes('qualified people')||n.includes('competenc'))return {nav:'equipment-master',label:'Resolve qualification blocker'};
 if(n.includes('customer')||n.includes('approval')||n.includes('change'))return {tab:'approvals',label:'Resolve approvals'};
 return {tab:'overview',label:'Open build context'};
}
