function simpleLineChart(rows,key,title,suffix='',prefix='',min=null,max=null){const vals=rows.map(r=>Number(r[key])).filter(Number.isFinite);if(!vals.length)return '<div class="empty compact">Not enough history for this trend.</div>';const lo=min!==null?min:Math.min(...vals),hi=max!==null?max:Math.max(...vals),span=Math.max(.001,hi-lo),W=620,H=210,pL=38,pR=16,pT=20,pB=34,pW=W-pL-pR,pH=H-pT-pB,pts=rows.map((r,i)=>{const v=Number(r[key]);if(!Number.isFinite(v))return null;const x=pL+i*(pW/Math.max(1,rows.length-1)),y=pT+pH-(v-lo)/span*pH;return {x,y,v,label:r.label}}).filter(Boolean),path=pts.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ');return `<svg class="kpi-line-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(title)}"><line x1="${pL}" y1="${pT+pH}" x2="${W-pR}" y2="${pT+pH}" class="kpi-axis"/><path d="${path}" class="kpi-line"/>${pts.map(p=>`<circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="4" class="kpi-dot"><title>${esc(p.label)}: ${prefix}${p.v.toFixed(1)}${suffix}</title></circle><text x="${p.x.toFixed(1)}" y="${H-12}" text-anchor="middle">${esc(p.label)}</text>`).join('')}<text x="${pL}" y="12">${prefix}${hi.toFixed(0)}${suffix}</text><text x="${pL}" y="${pT+pH-5}">${prefix}${lo.toFixed(0)}${suffix}</text></svg>`}

