 if(typeof x==='string'){const t=x.trim();if((t.startsWith('{')||t.startsWith('['))&&t.length>20){try{x=JSON.parse(t)}catch(_){return t.length>150?t.slice(0,147)+'…':t}}else return t.length>150?t.slice(0,147)+'…':t}
