 const accepted=(App.state.lessons||[]).filter(l=>l.requestId===r.id),pending=autoLessonProposals(r),decisions=lessonDecisionRows(r),acceptedDecisions=decisions.filter(x=>x.decision==='Accepted'),rejected=decisions.filter(x=>x.decision==='Rejected');
