function bindDragDrop(){let dragged=null;$$('.process-card[draggable="true"]').forEach(card=>{card.ondragstart=e=>{dragged=card;card.classList.add('dragging');e.dataTransfer.effectAllowed='move'};card.ondragend=()=>card.classList.remove('dragging');card.ondragover=e=>e.preventDefault();card.ondrop=async e=>{e.preventDefault();if(!dragged||dragged===card)return;const route=App.state.routes.find(r=>r.requestId===App.workspaceId);const from=Number(dragged.dataset.stepIndex),to=Number(card.dataset.stepIndex);const [moved]=route.steps.splice(from,1);route.steps.splice(to,0,moved);route.steps.forEach((s,i)=>s.order=i+1);P.audit(App.state,'Process route reordered','Request',App.workspaceId,from+1,to+1,`Moved ${moved.name}`);await persist();render();toast('Process route reordered and audit history updated.')}})}
function planBookingKey(b){return `${b.requestId||''}|${b.stepId||b.itemKey||b.id||''}|${b.taskType||b.type||''}`}
function planProposalChanges(before,after,requestIds){
 const ids=new Set(requestIds||[]),oldMap=new Map((before.bookings||[]).filter(b=>!ids.size||ids.has(b.requestId)).map(b=>[planBookingKey(b),b])),newMap=new Map((after.bookings||[]).filter(b=>!ids.size||ids.has(b.requestId)).map(b=>[planBookingKey(b),b])),rows=[];
 const desc=(s,b)=>{if(!b)return '—';const eq=s.equipment?.find(x=>x.id===b.equipmentId)?.name||'—',st=s.staff?.find(x=>x.id===b.staffId)?.name||'—';return `${P.formatDateTime(b.start)} · ${eq} · ${st}`};
 for(const key of new Set([...oldMap.keys(),...newMap.keys()])){const a=oldMap.get(key),b=newMap.get(key);if(!a&&b)rows.push({requestId:b.requestId,task:b.stepName||b.description||b.stepId,type:'Added',before:'—',after:desc(after,b)});else if(a&&!b)rows.push({requestId:a.requestId,task:a.stepName||a.description||a.stepId,type:'Removed',before:desc(before,a),after:'—'});else if(a&&b&&(a.start!==b.start||a.equipmentId!==b.equipmentId||a.staffId!==b.staffId||Number(a.durationHours)!==Number(b.durationHours)))rows.push({requestId:b.requestId,task:b.stepName||b.description||b.stepId,type:'Changed',before:desc(before,a),after:desc(after,b)});}
 return rows;
}
function portfolioProposalOnState(proposed,contextEvent=null){
 const includePotential=App.filters.planPotential!==false,results=new P.PlannerService().autoPlanPortfolio(proposed,{includePotential}),ids=proposed.requests.filter(r=>!['DELIVERED','CLOSED','RELEASED'].includes(r.status)).map(r=>r.id);for(const id of ids){const live=App.state.requests.find(r=>r.id===id),next=proposed.requests.find(r=>r.id===id);if(live?.currentCommitmentDate&&next?.forecastDate&&live.currentCommitmentDate!==next.forecastDate)next.pendingReplanContext=contextEvent?{eventId:contextEvent.id,reasonCategory:planningSituationReasonCategory(contextEvent),reason:`${contextEvent.type}: ${contextEvent.reason}`,eventAction:'portfolio proposal',createdAt:P.now()}:live.pendingReplanContext}return {results,ids}}
async function optimizePortfolio(opts={}){const contextEvent=opts?.contextEvent||null,proposed=P.deepClone(App.state),out=portfolioProposalOnState(proposed,contextEvent);if(out.results.some(x=>!x.ok)){planningPortfolioBlockedModal(out.results);return}showPlanProposal({mode:'portfolio',proposedState:proposed,requestIds:out.ids,results:out.results,contextEvent})}
function resumePendingPlanningSituationResolution(){
  const pending=App.pendingPlanningSituationResolution;
  if(!pending){render();return}
  App.pendingPlanningSituationResolution=null;
  setTimeout(()=>previewPlanningSituationChange(P.deepClone(pending.draft),P.deepClone(pending.opts||{})),0);
}
function planningPortfolioBlockedModal(results,retryDraft=null,retryOpts={}){
  const blocked=results.filter(x=>!x.ok);
  if(retryDraft)App.pendingPlanningSituationResolution={draft:P.deepClone(retryDraft),opts:P.deepClone(retryOpts||{})};
  const resolvable=new Set(['ZERO_REQUIRED_SKILL','ZERO_EQUIPMENT_CAPABILITY','STAFF_UNAVAILABLE','CAPACITY_UNRESOLVABLE','READINESS_SLOT_UNRESOLVABLE']);
  openModal('Complete resolution required',
    `<div class="resolution-focus"><span class="eyebrow">NOTHING HAS BEEN CHANGED</span><h2>${blocked.length} build${blocked.length===1?'':'s'} still prevent a complete solution</h2><p>Resolve the blocking item below. LabOS will automatically retry the complete portfolio change afterwards.</p></div>
     <div class="audit-guided-list">${blocked.map((x,i)=>`<div class="audit-guided-row"><div><strong>${esc(x.requestId)}</strong><small>${esc(x.error||'No feasible controlled plan.')}</small></div>${resolvable.has(x.code)?btn('Resolve →',`data-resolve-portfolio-blocker="${i}"`,'button small primary'):retryDraft?btn('Adjust proposed situation',`data-adjust-portfolio-blocker="${i}"`,'button small primary'):''}</div>`).join('')}</div>
     <details class="fold compact"><summary>Why LabOS stopped here</summary><p>The capacity change and resulting schedule are one transaction. A partial plan is never saved.</p></details>`,
    `${retryDraft?btn('Adjust situation','data-adjust-planning-situation','button secondary'):''}${btn('Cancel','data-modal-close','button')}`,true);
  setTimeout(()=>{
    $$('[data-resolve-portfolio-blocker]').forEach(b=>b.onclick=()=>{
      const x=blocked[Number(b.dataset.resolvePortfolioBlocker)];
      if(!x)return;
      closeModal();
      planningStructuralBlockerModal(x.requestId,{code:x.code,message:x.error,...(x.details||{})});
    });
    $$('[data-adjust-portfolio-blocker]').forEach(b=>b.onclick=()=>planningSituationModal(retryOpts.existingId||null));
    const a=$('[data-adjust-planning-situation]');if(a)a.onclick=()=>planningSituationModal(retryOpts.existingId||null);
  },0)
}
function previewPlanningSituationChange(draft,opts={}){const proposed=P.deepClone(App.state);P.ensureEnterpriseModel(proposed);proposed.planningEvents=proposed.planningEvents||[];const i=proposed.planningEvents.findIndex(x=>x.id===draft.id);if(i>=0)proposed.planningEvents[i]=P.deepClone(draft);else proposed.planningEvents.push(P.deepClone(draft));proposed.settings=proposed.settings||{};proposed.settings.planningNeedsReview=true;P.audit(proposed,opts.remove?'Planning situation removal proposed':opts.existingId?'Planning situation change proposed':'Planning situation proposed','Planning Situation',draft.id,opts.existingId?'Existing situation':'—',draft.active===false?'Remove':planningSituationLabel(draft),draft.reason||'Capacity change');const out=portfolioProposalOnState(proposed,draft);if(out.results.some(x=>!x.ok)){planningPortfolioBlockedModal(out.results,draft,opts);return}closeModal();showPlanProposal({mode:'portfolio',proposedState:proposed,requestIds:out.ids,results:out.results,contextEvent:draft})}
function showPlanProposal({mode,proposedState,requestIds,results=[],contextEvent=null}){
 const before=App.state,ids=requestIds||[],changes=planProposalChanges(before,proposedState,ids),forecasts=ids.map(id=>{const a=before.requests.find(r=>r.id===id),b=proposedState.requests.find(r=>r.id===id);return {id,title:a?.title||id,before:a?.forecastDate||null,after:b?.forecastDate||null,commit:a?.currentCommitmentDate||null,quality:b?.triage?.planQuality||'Not planned'}}).filter(x=>x.before!==x.after||mode==='single'),blocked=results.filter(x=>x.ok===false);
 App.pendingPlanProposal={mode,proposedState,requestIds:ids,contextEvent};
 const title=mode==='portfolio'?'Portfolio optimization proposal':'AUTO-PLAN proposal';
 openModal(title,`<div class="callout ${blocked.length?'warn':''}"><h3>Review before applying</h3><p>No live booking or committed delivery date has been changed yet. Review the forecast and resource movements below, then explicitly Accept or Reject the proposal.${contextEvent?` This proposal incorporates <strong>${esc(planningSituationLabel(contextEvent))}</strong>.`:''}</p></div>
 <div class="grid cols-4" style="margin-top:12px"><div class="mini-kpi"><span>Builds assessed</span><strong>${ids.length}</strong></div><div class="mini-kpi"><span>Forecast changes</span><strong>${forecasts.filter(x=>x.before!==x.after).length}</strong></div><div class="mini-kpi"><span>Booking changes</span><strong>${changes.length}</strong></div><div class="mini-kpi"><span>Structural gaps</span><strong>${blocked.length}</strong></div></div>
 <section class="report-section"><h3>Delivery forecast impact</h3>${forecasts.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Build</th><th>Current forecast</th><th>Proposed forecast</th><th>Current commitment</th><th>Plan quality</th></tr></thead><tbody>${forecasts.map(x=>`<tr><td><strong>${esc(x.id)}</strong><br><small>${esc(x.title)}</small></td><td>${P.formatDate(x.before)}</td><td>${P.formatDate(x.after)}</td><td>${P.formatDate(x.commit)}${x.commit&&x.after&&x.commit!==x.after?'<br><small class="warn-text">Replan decision required after acceptance</small>':''}</td><td>${esc(x.quality)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty compact">No forecast dates change.</div>'}</section>
 <section class="report-section"><h3>Resource / timing changes</h3>${changes.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Build</th><th>Task</th><th>Change</th><th>Current</th><th>Proposed</th></tr></thead><tbody>${changes.slice(0,100).map(x=>`<tr><td>${esc(x.requestId||'—')}</td><td>${esc(x.task)}</td><td>${esc(x.type)}</td><td>${esc(x.before)}</td><td>${esc(x.after)}</td></tr>`).join('')}</tbody></table></div>${changes.length>100?`<small>Showing first 100 of ${changes.length} changed bookings.</small>`:''}`:'<div class="empty compact">No booking assignment or timing changes.</div>'}</section>
 ${blocked.length?`<section class="report-section"><h3>Capability gaps</h3>${blocked.map(x=>`<div class="callout bad"><strong>${esc(x.requestId)}</strong><p>${esc(x.error)}</p></div>`).join('')}</section>`:''}
 <div class="field"><label>Planning decision note <small>optional but retained in audit history</small></label><textarea id="planProposalNote" placeholder="Why are you accepting or rejecting this plan?"></textarea></div>`,
 `${btn('Reject proposal','data-reject-plan-proposal','button danger')}${btn('Accept proposal','data-accept-plan-proposal','button primary')}`,true);
 setTimeout(()=>{const ac=$('[data-accept-plan-proposal]'),rj=$('[data-reject-plan-proposal]');if(ac)ac.onclick=acceptPlanProposal;if(rj)rj.onclick=rejectPlanProposal},0)
}
async function acceptPlanProposal(){const pp=App.pendingPlanProposal;if(!pp)return;const note=$('#planProposalNote')?.value.trim()||'Accepted after reviewing forecast and resource changes.',currentIdentity=P.deepClone(App.state.identity);App.state=P.deepClone(pp.proposedState);App.state.identity=currentIdentity;App.identity=new P.DemoIdentityProvider(App.state);populateRoles();App.state.settings=App.state.settings||{};App.state.settings.planningNeedsReview=false;P.audit(App.state,pp.mode==='portfolio'?'Portfolio plan proposal accepted':'AUTO-PLAN proposal accepted','Planning',pp.mode==='portfolio'?'PORTFOLIO':pp.requestIds[0],'Proposed','Applied',note);App.pendingPlanProposal=null;await persist();closeModal();render();toast(pp.contextEvent?'Capacity situation and complete portfolio replan applied together.':'Planning proposal accepted and applied. Committed dates remain unchanged until any required replan is separately approved.')}
async function rejectPlanProposal(){const pp=App.pendingPlanProposal;if(!pp)return;const note=$('#planProposalNote')?.value.trim()||'Proposal rejected; live plan retained.';P.audit(App.state,pp.mode==='portfolio'?'Portfolio plan proposal rejected':'AUTO-PLAN proposal rejected','Planning',pp.mode==='portfolio'?'PORTFOLIO':pp.requestIds[0],'Proposed','Rejected',note);App.pendingPlanProposal=null;await persist();closeModal();render();toast('Planning proposal rejected. Existing bookings and forecasts were retained.')}
async function autoPlan(id,contextEvent=null){const proposed=P.deepClone(App.state);try{const changes=new P.PlannerService().autoPlan(proposed,id),r=proposed.requests.find(x=>x.id===id),live=requestById(id);if(live?.currentCommitmentDate&&r?.forecastDate&&live.currentCommitmentDate!==r.forecastDate)r.pendingReplanContext=contextEvent?{eventId:contextEvent.id,reasonCategory:planningSituationReasonCategory(contextEvent),reason:`${contextEvent.type}: ${contextEvent.reason}`,eventAction:'planning proposal',createdAt:P.now()}:live.pendingReplanContext;showPlanProposal({mode:'single',proposedState:proposed,requestIds:[id],results:[{requestId:id,ok:true,bookings:changes.length,forecast:r.forecastDate,quality:r.triage?.planQuality}],contextEvent});}catch(e){if(['ZERO_EQUIPMENT_CAPABILITY','ZERO_REQUIRED_SKILL','STAFF_UNAVAILABLE','CAPACITY_UNRESOLVABLE','READINESS_SLOT_UNRESOLVABLE'].includes(e.code)){planningStructuralBlockerModal(id,e);return}console.error('AUTO-PLAN preview failed',e);planningUnexpectedErrorModal(id,e)}}
function replaceStateAtomically(next){for(const k of Object.keys(App.state))delete App.state[k];Object.assign(App.state,next)}
function planningUnexpectedErrorModal(requestId,error){
  openModal('Planning stopped safely',
    `<div class="resolution-focus"><span class="eyebrow">NO PARTIAL PLAN SAVED</span><h2>Planner could not complete this calculation</h2><p>${esc(error?.message||'Unexpected planning error')}</p></div><details class="fold compact"><summary>Technical detail</summary><p>${esc(error?.stack||String(error))}</p></details>`,
    `${btn('Close','data-modal-close','button')}${btn('Open build','data-planning-open-build','button secondary')}`
  );
  setTimeout(()=>{
    const b=$('[data-planning-open-build]');
    if(b)b.onclick=()=>{closeModal();openRequest(requestId,'planning')};
  },0);
}

function planningStructuralBlockerModal(requestId,error){
  const r=requestById(requestId);
  if(!r){toast('Build request no longer exists.',true);return}
  const code=error?.code||'PLANNING_BLOCKED',task=error?.taskName||'planned work';
  if(code==='ZERO_REQUIRED_SKILL'){planningSkillResolutionModal(requestId,error);return}
  if(code==='ZERO_EQUIPMENT_CAPABILITY'){planningEquipmentResolutionModal(requestId,error);return}
  if(code==='STAFF_UNAVAILABLE'){planningStaffAvailabilityResolutionModal(requestId,error);return}
  const cap=error?.capability||'',skillId=error?.skillId||'',skill=App.state.competencies.find(x=>x.id===skillId);
  openModal('Resolve planning blocker',
    `<div class="resolution-focus"><span class="eyebrow">CURRENT BLOCKER</span><h2>${esc(task)}</h2><p>${esc(error?.message||'No feasible controlled slot exists.')}</p></div>
     <div class="resolution-steps compact">
       <div class="resolution-step complete"><span class="resolution-index">✓</span><div><strong>Conflict identified</strong><small>Complete</small></div></div>
       <div class="resolution-step current"><span class="resolution-index">2</span><div><strong>Add resolvable capacity</strong><small>Current action</small></div></div>
       <div class="resolution-step pending"><span class="resolution-index">3</span><div><strong>Plan recalculates automatically</strong><small>Waiting</small></div></div>
     </div>
     <details class="fold compact"><summary>Why this is blocked</summary><p>${esc(error?.message||'')}</p></details>`,
    `${btn('Close','data-modal-close','button')}${cap?btn('Add / acquire capable equipment','data-capacity-equipment','button primary'):''}${skillId?btn(`Qualify another person${skill?' · '+esc(skill.name):''}`,'data-capacity-skill','button primary'):''}${!cap&&!skillId?btn('Review blocking capacity event','data-capacity-events','button primary'):''}`,
    true
  );
  setTimeout(()=>{
    const eq=$('[data-capacity-equipment]'),sk=$('[data-capacity-skill]'),ev=$('[data-capacity-events]');
    if(eq)eq.onclick=()=>{closeModal();capacityAcquisitionModal(requestId,cap,task)};
    if(sk)sk.onclick=()=>{closeModal();planningSkillResolutionModal(requestId,{code:'ZERO_REQUIRED_SKILL',skillId,skillName:skill?.name||skillId,taskName:task})};
    if(ev)ev.onclick=()=>{closeModal();planningCapacityEventResolver(requestId,error)};
  },0);
}

function planningSkillResolutionModal(requestId,error){
  const skillId=error.skillId,existing=App.state.competencies.find(x=>x.id===skillId),people=(App.state.staff||[]).filter(x=>x.available!==false),duration=Number(existing?.trainingDurationHours||4),validMonths=Number(existing?.validMonths||24),start=new Date(Date.now()+3600000).toISOString().slice(0,16);
  openModal('Resolve competency blocker',
    `<div class="resolution-focus"><span class="eyebrow">CURRENT BLOCKER</span><h2>${esc(error.taskName||'Planned work')}</h2><p>No currently associated person can satisfy <strong>${esc(existing?.name||error.skillName||skillId)}</strong>.</p></div>
     <div class="form-grid">
       <div class="field"><label>Competency</label><input id="psSkillName" value="${esc(existing?.name||error.skillName||skillId)}"></div>
       <div class="field"><label>Person to qualify</label><select id="psStaff">${people.map(st=>`<option value="${st.id}">${esc(st.name)}</option>`).join('')}</select></div>
       <div class="field"><label>Training duration (hours)</label><input id="psHours" type="number" min="0.25" step="0.25" value="${duration}"></div>
       <div class="field"><label>Qualification validity (months)</label><input id="psMonths" type="number" min="1" step="1" value="${validMonths}"></div>
       <div class="field full"><label>Earliest training time</label><input id="psStart" type="datetime-local" value="${esc(start)}"></div>
     </div>
     <details class="fold compact"><summary>What happens after this</summary><p>LabOS reserves a conflict-free training slot and creates the build plan after that qualification activity. Nothing is saved unless the complete resolution is feasible.</p></details>`,
    `${btn('Cancel','data-modal-close','button')}${btn('Schedule training & create plan','data-resolve-skill-plan','button primary')}`,
    true
  );
  setTimeout(()=>{
    const save=$('[data-resolve-skill-plan]');
    if(!save)return;
    save.onclick=async()=>{
      try{
        const staffId=$('#psStaff').value,h=Number($('#psHours').value),months=Number($('#psMonths').value),name=$('#psSkillName').value.trim(),from=$('#psStart').value;
        if(!staffId||!(h>0)||!(months>0)||!name||!from){toast('Person, competency, duration, validity and earliest time are required.',true);return}
        const next=P.deepClone(App.state);
        let sk=(next.competencies||[]).find(x=>x.id===skillId);
        if(!sk){sk={id:skillId,name,owner:next.identity?.name||'Lab Manager',description:`Competency created to resolve ${requestId} planning requirement.`,validMonths:months,trainingDurationHours:h,status:'Released'};next.competencies.push(sk)}
        else{sk.name=name;sk.validMonths=months;sk.trainingDurationHours=h}
        const st=next.staff.find(x=>x.id===staffId);
        if(!st)throw new Error('Selected person no longer exists.');
        st.competencies=st.competencies||[];
        if(!st.competencies.includes(skillId))st.competencies.push(skillId);
        const item={id:`GUIDED-Training-${requestId}-${staffId}-${skillId}`,itemKey:`Training-${staffId}-${skillId}-GUIDED-${requestId}`,type:'Training',staffId,skillId,targetId:staffId,targetName:`${st.name} · ${sk.name}`,durationHours:h,dueDate:requestById(requestId)?.requiredDate||P.todayISO(),validMonths:months,owner:sk.owner||'Lab Manager',reason:`Required to create a feasible plan for ${requestId}.`};
        const svc=new P.ResourceCareService(),slot=svc.nextResolvableSlot(next,item,new Date(from).toISOString()),scheduled=svc.scheduleResolved(next,item,slot.start,{durationHours:h,note:`Guided competency resolution for ${requestId}`}),changes=new P.PlannerService().autoPlan(next,requestId);
        replaceStateAtomically(next);
        P.audit(App.state,'Planning competency blocker resolved','Request',requestId,'No associated qualified capacity',`${st.name} training scheduled + plan created`,`${scheduled.record.start} · ${h} h · ${changes.length} booking(s)`);
        await persist();closeModal();toast(`Resolved. Training for ${st.name} is scheduled and the build plan was created automatically.`);resumePendingPlanningSituationResolution();
      }catch(err){toast(`Could not complete the full resolution: ${err.message}`,true)}
    };
  },0);
}

function planningEquipmentResolutionModal(requestId,error){
  const cap=error.capability||'',task=error.taskName||'planned work';
  openModal('Resolve equipment capability blocker',
    `<div class="resolution-focus"><span class="eyebrow">CURRENT BLOCKER</span><h2>${esc(task)}</h2><p>No registered asset provides <strong>${esc(cap)}</strong>.</p></div>
     <div class="card"><span class="eyebrow">AVAILABLE / RECEIVED ASSET</span><div class="form-grid">
       <div class="field"><label>Asset name</label><input id="peName" placeholder="Equipment name"></div>
       <div class="field"><label>Capability</label><input id="peCap" value="${esc(cap)}"></div>
       <div class="field"><label>Equipment type</label><input id="peType" value="${esc(cap)}"></div>
       <div class="field"><label>Location</label><input id="peLoc" value="Prototype Lab"></div>
       <div class="field"><label>Calibration duration (hours)</label><input id="peCal" type="number" min="0.25" step="0.25" value="4"></div>
       <div class="field"><label>Maintenance duration (hours)</label><input id="peMnt" type="number" min="0.25" step="0.25" value="4"></div>
     </div></div>
     <details class="fold compact"><summary>No physical asset exists yet</summary><p>Use the guided acquisition route. LabOS will keep the build blocked until a real asset is ordered, received, registered and commissioned.</p>${btn('Start guided acquisition','data-start-capacity-acquisition','button small secondary')}</details>`,
    `${btn('Cancel','data-modal-close','button')}${btn('Register asset & create plan','data-register-capacity-asset','button primary')}`,
    true
  );
  setTimeout(()=>{
    const acq=$('[data-start-capacity-acquisition]'),save=$('[data-register-capacity-asset]');
    if(acq)acq.onclick=()=>{closeModal();capacityAcquisitionModal(requestId,cap,task)};
    if(!save)return;
    save.onclick=async()=>{
      try{
        const name=$('#peName').value.trim(),capability=$('#peCap').value.trim(),type=$('#peType').value.trim(),location=$('#peLoc').value.trim(),cal=Number($('#peCal').value),mnt=Number($('#peMnt').value);
        if(!name||!capability||!(cal>0)||!(mnt>0)){toast('Asset name, capability and positive readiness durations are required.',true);return}
        const next=P.deepClone(App.state),id=P.uid('EQ');
        next.equipment.push({id,name,capability,equipmentType:type||name,status:'Commissioning',location:location||'Prototype Lab',hourlyCost:0,calibrationRequired:true,calibrationStatus:'Due',calibrationDue:P.todayISO(),calibrationCertificateValid:false,calibrationDurationHours:cal,maintenanceStatus:'Valid',maintenanceDue:new Date(Date.now()+120*86400000).toISOString().slice(0,10),maintenanceDurationHours:mnt});
        const changes=new P.PlannerService().autoPlan(next,requestId);
        replaceStateAtomically(next);
        P.audit(App.state,'Planning capability blocker resolved','Request',requestId,'Zero capable equipment',`${id} · ${name}`,`Capability ${capability}; prerequisite readiness automatically reserved; ${changes.length} booking(s)`);
        await persist();closeModal();toast(`Resolved. ${name} is registered and required readiness work plus the build plan were scheduled automatically.`);resumePendingPlanningSituationResolution();
      }catch(err){toast(`Could not complete the full resolution: ${err.message}`,true)}
    };
  },0);
}

function planningStaffAvailabilityResolutionModal(requestId,error){
  const skill=App.state.competencies.find(x=>x.id===error.skillId),taskName=error.taskName||'Planned work',associated=(App.state.staff||[]).filter(st=>(st.competencies||[]).includes(error.skillId)||(App.state.trainingCertificates||[]).some(c=>c.staffId===st.id&&c.skillId===error.skillId));
  const viable=[];
  for(const st of associated){
    if(st.available===false)continue;
    try{
      const sim=P.deepClone(App.state),rr=sim.requests.find(x=>x.id===requestId);rr.planningPreferences=rr.planningPreferences||{};rr.planningPreferences.staffByTaskName=rr.planningPreferences.staffByTaskName||{};rr.planningPreferences.staffByTaskName[taskName]=st.id;
      new P.PlannerService().autoPlan(sim,requestId);viable.push(st);
    }catch(_){}
  }
  if(!viable.length){
    openModal('Resolve staff availability blocker',
      `<div class="resolution-focus"><span class="eyebrow">CURRENT BLOCKER</span><h2>${esc(taskName)}</h2><p>No currently available, qualified person can produce a complete feasible plan for this work.</p></div>
       <div class="callout warn"><strong>No false alternative is offered</strong><p>LabOS tested the associated people against the complete build plan. None can resolve the blocker end-to-end.</p></div>
       <details class="fold compact"><summary>Create additional qualified capacity</summary><p>Use the guided qualification workflow. LabOS will only commit it if training plus the resulting build plan are both feasible.</p></details>`,
      `${btn('Cancel','data-modal-close','button')}${error.skillId?btn('Qualify another person','data-pa-train','button primary'):''}`,
      true
    );
    setTimeout(()=>{const tr=$('[data-pa-train]');if(tr)tr.onclick=()=>{closeModal();planningSkillResolutionModal(requestId,{code:'ZERO_REQUIRED_SKILL',skillId:error.skillId,skillName:skill?.name||error.skillId,taskName})}},0);
    return;
  }
  openModal('Resolve staff availability blocker',
    `<div class="resolution-focus"><span class="eyebrow">PREVALIDATED RESOLUTION</span><h2>${esc(taskName)}</h2><p>Select a person only from the prevalidated options below. Each option has already produced a complete feasible plan with this exact assignment retained.</p></div>
     <div class="field"><label>Assign person</label><select id="paStaff">${viable.map(st=>`<option value="${st.id}">${esc(st.name)} · complete-plan feasible</option>`).join('')}</select></div>
     <details class="fold compact"><summary>What LabOS will change</summary><p>The selected person is fixed as the planning preference for this task, the complete build is replanned, and the change is committed only if the same full simulation still succeeds.</p></details>`,
    `${btn('Cancel','data-modal-close','button')}${btn('Assign & create complete plan','data-pa-confirm','button primary')}`,
    true
  );
  setTimeout(()=>{
    const save=$('[data-pa-confirm]');
    if(!save)return;
    save.onclick=async()=>{
      try{
        const id=$('#paStaff').value;if(!id){toast('Select a person.',true);return}
        const next=P.deepClone(App.state),st=next.staff.find(x=>x.id===id),rr=next.requests.find(x=>x.id===requestId);if(!st||!rr)throw new Error('Selected person or build no longer exists.');
        if(st.available===false)throw new Error(`${st.name} is no longer available.`);
        rr.planningPreferences=rr.planningPreferences||{};rr.planningPreferences.staffByTaskName=rr.planningPreferences.staffByTaskName||{};rr.planningPreferences.staffByTaskName[taskName]=id;
        const changes=new P.PlannerService().autoPlan(next,requestId),assigned=(next.bookings||[]).filter(b=>b.requestId===requestId&&b.stepName===taskName);
        if(!assigned.length||assigned.some(b=>b.staffId!==id))throw new Error('The selected person could not be retained for the affected task.');
        replaceStateAtomically(next);
        P.audit(App.state,'Staff availability blocker resolved','Request',requestId,error.staffId||'Unavailable assignment',`${st.name} assigned`,`${taskName} · ${changes.length} booking(s) replanned and verified`);
        await persist();closeModal();render();toast(`${st.name} assigned and the complete build plan updated.`);resumePendingPlanningSituationResolution();
      }catch(err){toast(`Resolution not applied: ${err.message}`,true)}
    };
  },0);
}

function planningCapacityEventResolver(requestId,error){
  const events=(App.state.planningEvents||[]).filter(x=>x.active!==false);
  if(!events.length){planningUnexpectedErrorModal(requestId,error);return}
  openModal('Resolve capacity constraint',
    `<div class="resolution-focus"><span class="eyebrow">CURRENT BLOCKER</span><h2>${esc(error?.taskName||'No feasible slot')}</h2><p>Select the real capacity constraint to update. LabOS will recalculate from the changed availability evidence.</p></div><div class="field"><label>Blocking / relevant planning situation</label><select id="pceEvent">${events.map(x=>`<option value="${x.id}">${esc(planningSituationLabel(x))}</option>`).join('')}</select></div>`,
    `${btn('Cancel','data-modal-close','button')}${btn('Update situation & replan','data-pce-open','button primary')}`
  );
  setTimeout(()=>{const b=$('[data-pce-open]');if(b)b.onclick=()=>{const id=$('#pceEvent').value;closeModal();planningSituationModal(id)}},0);
}

function capacityAcquisitionModal(requestId,capability,taskName,acqId=null){
  App.state.capacityAcquisitions=App.state.capacityAcquisitions||[];
  let a=acqId?App.state.capacityAcquisitions.find(x=>x.id===acqId):null;
  if(!a){
    a={id:P.uid('CAPACQ'),requestId,capability,taskName,status:'Requirement',step:0,createdAt:P.now(),owner:App.state.identity.name,evidence:[]};
    App.state.capacityAcquisitions.push(a);
    App.state.actions=App.state.actions||[];
    App.state.actions.unshift({id:P.uid('ACT'),category:'Planning',title:`Acquire required capability · ${capability}`,why:`${requestId} cannot be planned because no registered asset provides ${capability}.`,impact:'The build remains unscheduled until a real asset is received, registered and commissioning is scheduled.',owner:a.owner,due:requestById(requestId)?.requiredDate||P.todayISO(),severity:'warn',resolve:'readiness',requestId,capacityAcquisitionId:a.id});
    persist();
  }
  const labels=['Confirm requirement','Approve source / solution','Order / arrange','Receive & register asset','Commission & create plan'],step=Math.max(0,Math.min(4,Number(a.step||0)));
  let fields='';
  if(step===0)fields=`<div class="field"><label>Owner</label><input id="caOwner" value="${esc(a.owner||App.state.identity.name)}"></div>`;
  if(step===1)fields=`<div class="form-grid"><div class="field"><label>Supplier / source</label><input id="caSupplier" value="${esc(a.supplier||'')}"></div><div class="field"><label>Approved by</label><input id="caApproved" value="${esc(a.approvedBy||'')}"></div><div class="field"><label>Expected availability</label><input id="caExpected" type="date" value="${esc(a.expectedDate||'')}"></div></div>`;
  if(step===2)fields=`<div class="field"><label>PO / lease / transfer reference</label><input id="caOrder" value="${esc(a.orderRef||'')}"></div>`;
  if(step===3)fields=`<div class="form-grid"><div class="field"><label>Received asset name</label><input id="caName" value="${esc(a.assetName||'')}"></div><div class="field"><label>Equipment type</label><input id="caType" value="${esc(a.equipmentType||capability)}"></div><div class="field"><label>Location</label><input id="caLocation" value="${esc(a.location||'Prototype Lab')}"></div><div class="field"><label>Calibration duration (hours)</label><input id="caCal" type="number" min="0.25" step="0.25" value="${Number(a.calibrationDurationHours||4)}"></div><div class="field"><label>Maintenance duration (hours)</label><input id="caMnt" type="number" min="0.25" step="0.25" value="${Number(a.maintenanceDurationHours||4)}"></div></div>`;
  if(step===4)fields=`<div class="callout"><strong>${esc(a.assetName||a.equipmentId||'Received asset')}</strong><p>LabOS will schedule mandatory readiness work and create the build plan atomically. Execution remains blocked until the scheduled readiness evidence is completed.</p></div>`;
  openModal('Guided capacity resolution',
    `<div class="resolution-focus"><span class="eyebrow">${esc(requestId)} · ${esc(capability)}</span><h2>${esc(labels[step])}</h2><p>${esc(taskName||a.taskName||'Required build capability')}</p></div>
     <div class="resolution-steps compact">${labels.map((l,i)=>`<div class="resolution-step ${i<step?'complete':i===step?'current':'pending'}"><span class="resolution-index">${i<step?'✓':i+1}</span><div><strong>${esc(l)}</strong><small>${i<step?'Complete':i===step?'Current action':'Waiting'}</small></div></div>`).join('')}</div>
     ${fields}<div class="field"><label>Evidence / decision</label><textarea id="caEvidence" placeholder="Reference or objective evidence for this step"></textarea></div>`,
    `${btn('Close','data-modal-close','button')}${btn(step===4?'Commission & create plan':'Complete step →','data-capacity-next','button primary')}`,
    true
  );
  setTimeout(()=>{
    const b=$('[data-capacity-next]');if(!b)return;
    b.onclick=async()=>{
      try{
        const ev=$('#caEvidence').value.trim();if(!ev){toast('Record objective evidence or the decision reference for this step.',true);return}
        if(step===0){a.owner=$('#caOwner').value.trim()||App.state.identity.name}
        else if(step===1){a.supplier=$('#caSupplier').value.trim();a.approvedBy=$('#caApproved').value.trim();a.expectedDate=$('#caExpected').value;if(!a.supplier||!a.approvedBy||!a.expectedDate){toast('Supplier/source, approver and expected availability are required.',true);return}}
        else if(step===2){a.orderRef=$('#caOrder').value.trim();if(!a.orderRef){toast('Order/lease/transfer reference is required.',true);return}}
        else if(step===3){
          const name=$('#caName').value.trim(),cal=Number($('#caCal').value),mnt=Number($('#caMnt').value);if(!name||!(cal>0)||!(mnt>0)){toast('Received asset name and positive calibration/maintenance durations are required.',true);return}
          const id=P.uid('EQ');App.state.equipment.push({id,name,capability:a.capability,equipmentType:$('#caType').value.trim()||a.capability,status:'Commissioning',location:$('#caLocation').value.trim()||'Prototype Lab',hourlyCost:0,calibrationRequired:true,calibrationStatus:'Due',calibrationDue:P.todayISO(),calibrationCertificateValid:false,calibrationDurationHours:cal,maintenanceStatus:'Valid',maintenanceDue:new Date(Date.now()+120*86400000).toISOString().slice(0,10),maintenanceDurationHours:mnt});
          Object.assign(a,{equipmentId:id,assetName:name,calibrationDurationHours:cal,maintenanceDurationHours:mnt,status:'Received'});
        }else{
          const next=P.deepClone(App.state),changes=new P.PlannerService().autoPlan(next,requestId),acq=next.capacityAcquisitions.find(x=>x.id===a.id);acq.status='Commissioning / plan created';acq.step=5;acq.completedPlanningAt=P.now();replaceStateAtomically(next);const live=App.state.capacityAcquisitions.find(x=>x.id===a.id),eq=App.state.equipment.find(x=>x.id===live.equipmentId);App.state.actions=(App.state.actions||[]).filter(x=>x.capacityAcquisitionId!==a.id);
          P.audit(App.state,'Capacity acquisition reached commissioning','Equipment',eq?.id||live.equipmentId,'Acquisition','Plan created',`${requestId} · ${changes.length} booking(s); readiness evidence still required before execution`);
          await persist();closeModal();toast('Capacity is registered, readiness work is scheduled and the build plan was created. Complete the scheduled readiness evidence before execution.');resumePendingPlanningSituationResolution();return;
        }
        a.evidence=a.evidence||[];a.evidence[step]={at:P.now(),actor:App.state.identity.name,text:ev};a.step=step+1;a.status=labels[Math.min(4,a.step)];P.audit(App.state,'Capacity acquisition advanced','Capacity Acquisition',a.id,labels[step],a.status,ev);await persist();closeModal();capacityAcquisitionModal(requestId,capability,taskName,a.id);
      }catch(err){toast(`Could not complete this guided step: ${err.message}`,true)}
    };
  },0);
}

function commitmentDecisionQueueModal(){const rows=(App.state.requests||[]).filter(r=>r.currentCommitmentDate&&r.forecastDate&&r.currentCommitmentDate!==r.forecastDate&&!['CLOSED','DELIVERED'].includes(r.status));openModal('Commitment decisions',rows.length?`<div class="callout warn"><strong>${rows.length} commitment decision${rows.length===1?'':'s'} require review.</strong><p>A forecast has moved away from the date currently promised. Review and either retain the current commitment or accept the proposed date with a reason.</p></div><div class="commitment-decision-list">${rows.map(r=>{const a=new Date(r.currentCommitmentDate),b=new Date(r.forecastDate),d=Math.round((b-a)/86400000);return `<div class="commitment-decision-row"><div><strong>${esc(r.id)} · ${esc(r.productFamily)}</strong><small>Current ${P.formatDate(r.currentCommitmentDate)} → forecast ${P.formatDate(r.forecastDate)} · ${d>0?'+':''}${d} day(s)</small><span>${esc(r.pendingReplanContext?.reason||'Planning forecast changed.')}</span></div>${btn('Review decision →',`data-review-commitment="${r.id}"`,'button small primary')}</div>`}).join('')}</div>`:'<div class="callout good"><strong>✓ No commitment movements await a decision.</strong></div>',btn('Close','data-modal-close','button'),true);setTimeout(()=>{$$('[data-review-commitment]').forEach(b=>b.onclick=()=>{const id=b.dataset.reviewCommitment;closeModal();commitTriage(id)})},0)}
async function commitTriage(id){const r=requestById(id),mat=P.materialPlanningAssessment(App.state,r),proc=P.processPlanningAssessment(App.state,r);if(!can('triage')&&currentRole()!=='administrator'){toast('Lab Planner role is required to commit timing.',true);return}if(!mat.planningReady||!proc.ready){toast('Cannot commit timing until material feasibility and process/test definition are complete.',true);return}if(!r.triage?.forecastDate){toast('Run AUTO-PLAN before committing the timing forecast.',true);return}const forecast=r.triage.forecastDate,current=r.currentCommitmentDate||r.originalCommitmentDate;if(r.originalCommitmentDate&&current&&forecast!==current){const ctx=r.pendingReplanContext||{},events=(App.state.planningEvents||[]).filter(x=>x.active!==false||x.id===ctx.eventId);openModal(`Commit replan · ${r.id}`,`<div class="callout warn"><h3>Committed date movement requires a reason</h3><p>Original commitment <strong>${P.formatDate(r.originalCommitmentDate)}</strong> · current commitment <strong>${P.formatDate(current)}</strong> · proposed commitment <strong>${P.formatDate(forecast)}</strong>. The original date will never be overwritten.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Reason category</label><select id="replanCategory">${['Vacation / staff absence','Equipment outage','Lab closure / capacity loss','Calibration / maintenance','Material delay','Process / test development','Scope / quantity change','Engineering change','Priority change','Quality / rework','Capacity / congestion','Other'].map(x=>`<option ${ctx.reasonCategory===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Linked planning situation</label><select id="replanEvent"><option value="">None / not applicable</option>${events.map(x=>`<option value="${x.id}" ${ctx.eventId===x.id?'selected':''}>${esc(planningSituationLabel(x))}</option>`).join('')}</select></div><div class="field full"><label>Reason / explanation <small>required</small></label><textarea id="replanReason" placeholder="What caused the commitment to move?">${esc(ctx.reason||'')}</textarea></div></div>`,`${btn('Keep current commitment','data-modal-close','button')}${btn('Accept new commitment','data-accept-replan','button primary')}`,true);setTimeout(()=>{$('[data-accept-replan]').onclick=async()=>{const reason=$('#replanReason').value.trim(),category=$('#replanCategory').value,eventId=$('#replanEvent').value||null;if(!reason){toast('Every replan requires an explanation.',true);return}try{P.recordCommitment(App.state,r,forecast,{reasonCategory:category,reason,eventId})}catch(e){toast(e.message,true);return}const prev=r.status;r.triage.status='Committed';r.status=r.currentGate='LAB TRIAGE';r.pendingReplanContext=null;App.state.actions=App.state.actions.filter(a=>!(a.requestId===id&&/triage|timing|feasibility/i.test(a.title)));P.audit(App.state,'Lab timing replanned & committed','Request',id,current,forecast,`${category} · ${reason}`);await persist();closeModal();render();toast(`Replan committed. New commitment ${P.formatDate(forecast)}; original ${P.formatDate(r.originalCommitmentDate)} retained.`)}},0);return}const rec=P.recordCommitment(App.state,r,forecast);const prev=r.status;r.triage.status='Committed';r.status=r.currentGate='LAB TRIAGE';r.pendingReplanContext=null;App.state.actions=App.state.actions.filter(a=>!(a.requestId===id&&/triage|timing|feasibility/i.test(a.title)));P.audit(App.state,rec.type==='initial'?'Lab timing committed':'Lab timing recommitted','Request',id,prev,'LAB TRIAGE',`Forecast ${forecast}; original commitment ${r.originalCommitmentDate}; margin ${r.triage.slackDays} days`);await persist();render();toast(rec.type==='initial'?`Initial lab commitment recorded: ${P.formatDate(forecast)}.`:'Timing commitment confirmed with no date movement.')}

async function confirmRoute(id){const route=App.state.routes.find(x=>x.requestId===id),r=requestById(id);if(!route){toast('No route found.',true);return}if(!can('route:edit')&&currentRole()!=='administrator'){toast('Process Engineer role is required to confirm the route.',true);return}route.proposed=false;route.confirmed=true;route.assessedAt=P.now();route.steps.forEach(s=>{if(s.status==='Proposed')s.status='Planned'});if(['SUBMITTED','FEASIBILITY'].includes(r.status))r.status=r.currentGate='PROCESS DEFINITION';P.audit(App.state,'Process route assessed and confirmed','Request',id,'Proposed route','Confirmed route',`Route ${route.revision}; standard/new/modified decisions retained`);await persist();render();toast('Route confirmed. Complete any process/test development planning inputs before AUTO-PLAN.')}
async function closeRequest(id){const r=requestById(id);if(r.status!=='DELIVERED'){toast('Request can only close after delivery acknowledgement.',true);return}if(App.state.deviations.some(d=>d.requestId===id&&d.releaseHold&&d.status!=='CLOSED')){toast('Cannot close while release holds remain open.',true);return}const pendingLessons=autoLessonProposals(r);if(pendingLessons.length){App.workspaceTab='closeout';render();toast(`Review ${pendingLessons.length} lessons-learned proposal${pendingLessons.length===1?'':'s'} before closing.`,true);return}new P.LearningService().captureBuild(App.state,id);const prev=r.status;r.status=r.currentGate='CLOSED';r.archived=true;r.archivedAt=P.now();r.closedAt=P.now();P.audit(App.state,'Prototype request closed & learning captured','Request',id,prev,'CLOSED','Delivery acknowledged; actual duration/yield/rework/issues retained for future same-product planning');await persist();render();toast('Request closed and archived. It remains searchable under Prototype → Archived.')}
function changeAssuranceModal(requestId){const r=requestById(requestId),current=P.ensureAssuranceProfile(r),opts=Object.values(P.ASSURANCE_PROFILES);openModal('Change build purpose / assurance level',`<div class="callout"><h3>Scale the process to the purpose of the build</h3><p>Choose the lowest level that still provides the evidence you actually need. Product-safety-relevant work cannot be reduced below Validation.</p></div><div class="assurance-choice-grid" style="margin-top:12px">${opts.map(x=>`<label class="assurance-choice level-${x.formalLevel}"><input type="radio" name="assuranceChange" value="${x.id}" ${x.id===current.id?'checked':''}><strong>${esc(x.code)} · ${esc(x.label)}</strong><span>${esc(x.tagline)}</span><small>${esc(x.description)}</small></label>`).join('')}</div>`,`${btn('Cancel','data-modal-close','button')}${btn('Apply level','data-save-assurance','button primary')}`,true);setTimeout(()=>{$('[data-save-assurance]').onclick=async()=>{let id=$('input[name="assuranceChange"]:checked')?.value||current.id;if(r.productSafety&&P.ASSURANCE_PROFILES[id].formalLevel<2){toast('Product-safety-relevant builds require at least Validation.',true);id='validation'}const prev=r.assuranceProfile;r.assuranceProfile=id;P.ensureApprovalRecords(App.state,r);const route=App.state.routes.find(x=>x.requestId===requestId);if(route)route.confirmed=false;r.triage=null;r.forecastDate=null;P.audit(App.state,'Build assurance level changed','Request',requestId,prev,id,'Purpose/formality changed; route and timing require reconfirmation');await persist();closeModal();render();toast(`Build purpose changed to ${P.ASSURANCE_PROFILES[id].label}. Reconfirm route and timing.`)}} ,0)}
function showReadiness(id){const rs=new P.ReadinessService(App.state).evaluate(id);openModal('Build Readiness Review',`<div class="callout ${rs.ready?'':'warn'}"><h3>${rs.ready?'READY':'NOT READY'}</h3><p>${rs.ready?'Configured readiness conditions are satisfied.':'Resolve the exact blockers below. Passing the gate requires objective evidence, not a Complete button.'}</p></div><div style="height:10px"></div>${readinessRows(rs.checks)}${rs.issues.map(blockerBox).join('')}`,btn('Close','data-modal-close','button'))}
function routeStepsFromProcessIds(ids){return (ids||[]).map((pid,i)=>{const p=App.state.processes.find(x=>x.id===pid);return {id:P.uid('STEP'),order:i+1,processId:pid,name:p?.name||pid,processRevision:p?.revision||'A',type:'standard',owner:'Unassigned',planned:null,status:'Proposed',readiness:'pending',parallelGroup:null,optional:false}})}
function resetCopiedStep(s,i){const p=App.state.processes.find(x=>x.id===s.processId);return {...P.deepClone(s),id:P.uid('STEP'),order:i+1,name:p?.name||s.name,processRevision:p?.revision||s.processRevision||'A',status:'Proposed',readiness:s.type==='standard'?'pending':'blocked',planned:null,startedAt:null,startedBy:null,completedAt:null,completedBy:null,equipmentId:null,executionSerial:null,evidence:null,actualDurationHours:null}}
function routeSourceModal(requestId){const r=requestById(requestId),route=App.state.routes.find(x=>x.requestId===requestId),product=App.state.products.find(p=>p.id===r.productId);const prior=App.state.routes.filter(x=>x.requestId!==requestId&&x.steps?.length).map(x=>{const q=requestById(x.requestId);return {route:x,request:q}}).sort((a,b)=>(b.request?.productId===r.productId)-(a.request?.productId===r.productId));openModal('Choose build route starting point',`<div class="route-choice-grid"><label class="route-choice"><input type="radio" name="routeMode" value="scratch"><strong>Start from scratch</strong><span>Blank route. Add only the operations needed for this build.</span></label><label class="route-choice"><input type="radio" name="routeMode" value="product" checked><strong>Use product standard route</strong><span>${esc(product?.family||r.productFamily)} default · ${(product?.defaultRoute||[]).length} step(s). You can edit it freely for this build.</span></label><label class="route-choice"><input type="radio" name="routeMode" value="previous"><strong>Copy a previous build</strong><span>Reuse a route that worked before, then modify it without changing the original build record.</span></label></div><div id="routePreviousPick" class="field hidden" style="margin-top:14px"><label>Previous build route</label><select id="routePrevious">${prior.map(x=>`<option value="${x.route.requestId}">${x.request?.productId===r.productId?'★ ':''}${esc(x.route.requestId)} · ${esc(x.request?.productFamily||'Unknown product')} · ${x.route.steps.length} steps</option>`).join('')}</select><small>★ Same product family is listed first.</small></div><div class="callout" style="margin-top:14px"><h3>This is a starting point, not a locked template</h3><p>The selected route is copied into this request. From then on it can be reordered, extended, shortened, or individual steps can be changed to standard / modified / new methods.</p></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Use selected route',`data-apply-route-source="${requestId}"`,'button primary')}`,true);setTimeout(()=>{const radios=$$('input[name="routeMode"]'),pick=$('#routePreviousPick');radios.forEach(x=>x.onchange=()=>pick.classList.toggle('hidden',x.value!=='previous'||!x.checked));$(`[data-apply-route-source="${requestId}"]`).onclick=async()=>{const mode=$('input[name="routeMode"]:checked')?.value||'product';let steps=[],source={mode};if(mode==='scratch')steps=[];else if(mode==='product'){steps=routeStepsFromProcessIds(product?.defaultRoute?.length?product.defaultRoute:P.getDefaultRoute(r.productId));source.productId=r.productId;}else{const srcId=$('#routePrevious')?.value,src=App.state.routes.find(x=>x.requestId===srcId);if(!src){toast('Choose a previous route.',true);return}steps=src.steps.map(resetCopiedStep);source={mode:'previous',requestId:srcId,revision:src.revision};}route.steps=steps;route.revision=String.fromCharCode((route.revision||'A').charCodeAt(0)+1);route.confirmed=false;route.proposed=true;route.source=source;route.reworkLoops=[];route.steps.forEach((s,i)=>s.order=i+1);if(P.ensureReusePackage(r).route.mode!=='none')P.markBuildSpecificDelta(App.state,r,'Process route','Route baseline replaced for this build');P.audit(App.state,'Build route starting point changed','Request',requestId,'Previous request route',mode,mode==='scratch'?'Started from blank route':mode==='product'?`Copied product standard route ${r.productId}`:`Copied route from ${source.requestId}`);await persist();closeModal();render();toast('Route copied into this build. Edit it as needed, then confirm it for planning.')}} ,0)}
