async function moveRouteStep(stepId,delta){const route=App.state.routes.find(r=>r.requestId===App.workspaceId),i=route?.steps.findIndex(x=>x.id===stepId);if(i<0)return;const j=i+delta;if(j<0||j>=route.steps.length)return;[route.steps[i],route.steps[j]]=[route.steps[j],route.steps[i]];route.steps.forEach((x,k)=>x.order=k+1);route.confirmed=false;route.proposed=true;if(P.ensureReusePackage(requestById(App.workspaceId)).route.mode!=='none')P.markBuildSpecificDelta(App.state,requestById(App.workspaceId),'Process route','Route order changed for this build');P.audit(App.state,'Route step reordered','Request',App.workspaceId,i+1,j+1,route.steps[j].name);await persist();render()}
