function showStep(id){const route=App.state.routes.find(r=>r.requestId===App.workspaceId),s=route.steps.find(x=>x.id===id),p=App.state.processes.find(x=>x.id===s.processId),dev=App.state.processDevelopments.find(x=>x.requestId===App.workspaceId&&(x.libraryCandidate===s.processId||x.name.includes(s.name)));openModal(`${s.name} · Step ${s.order}`,`<div class="grid cols-2"><div class="card"><h3>Controlled step</h3><div class="score-row"><span>Type</span><strong>${esc(s.type)}</strong></div><div class="score-row"><span>Process revision</span><strong>${esc(s.processRevision)}</strong></div><div class="score-row"><span>Owner</span><strong>${esc(s.owner)}</strong></div><div class="score-row"><span>Planned</span><strong>${P.formatDateTime(s.planned)}</strong></div><div class="score-row"><span>Status</span>${status(s.status)}</div></div><div class="card"><h3>Requirements</h3>${(p?.requiredEvidence||['Controlled evidence']).map(x=>`<div class="score-row"><span>${esc(x)}</span><span class="warnmark">○</span></div>`).join('')}</div></div>${dev?`<div style="height:12px"></div><div class="callout warn"><h3>${esc(dev.conclusion)}</h3><p>Development ${esc(dev.id)} · ${esc(dev.status)}. Complete development gates before this process can be released for controlled execution.</p></div>`:''}`,btn('Close','data-modal-close','button'),true)}
async function requestControlPlanReview(id){const cp=App.state.controlPlans.find(x=>x.id===id);if(!cp){toast('Control Plan not found.',true);return}if(!(can('controlplan:edit')||currentRole()==='administrator')){toast('Current role cannot submit Control Plans for review.',true);return}const invalid=(cp.characteristics||[]).filter(c=>c.classification&&!P.controlCharacteristicReady(c));if(invalid.length){toast('Complete all controlled characteristic definitions before requesting review.',true);return}if(cp.status!=='Draft'){toast(`Control Plan is already ${cp.status}.`,cp.status!=='Review requested');return}const prev=cp.status;cp.status='Review requested';cp.reviewRequestedAt=P.now();cp.reviewRequestedBy=App.state.identity.name;P.audit(App.state,'Control Plan review requested','Control Plan',id,prev,cp.status,`Independent approval requested by ${App.state.identity.name}`);await persist();render();toast('Control Plan submitted for independent review.')}
async function approveCp(id){const cp=App.state.controlPlans.find(x=>x.id===id);if(!cp){toast('Control Plan not found.',true);return}const ap=controlPlanApprovalState(cp);if(!ap.canApprove){toast(ap.reason,true);return}try{new P.ControlPlanService(App.state).approve(id);const r=cp.buildSpecific?requestById(cp.buildRequestId):null;if(r){const pack=P.ensureReusePackage(r);if(pack.controlPlan){pack.controlPlan.mode='modified';pack.controlPlan.buildSpecificId=cp.id;pack.controlPlan.approvedRevision=cp.revision;pack.controlPlan.approvedAt=cp.approvedAt}P.ensureApprovalRecords(App.state,r)}await persist();render();toast(`Control Plan ${cp.id} Rev ${cp.revision} formally approved by ${App.state.identity.name}.`)}catch(e){toast(e.message,true)}}
async function approveRecord(id){const a=App.state.approvals.find(x=>x.id===id);if(!a){toast('Approval record not found.',true);return}if(!canApproveRecord(a)){toast(`This approval requires ${a.role}.`,true);return}if(a.status==='Approved'){toast('Approval is already complete.');return}const prev=a.status;a.status='Approved';a.person=App.state.identity.name;a.timestamp=P.now();a.comment=a.comment&&a.comment!=='Pending'?a.comment:'Approved in controlled workflow';if(a.stage==='build-change'){const r=requestById(a.requestId);if(r&&P.buildChangeApprovalsComplete(App.state,r,a.changeArea)){const pack=P.ensureReusePackage(r);(pack.deltas||[]).filter(d=>d.area===a.changeArea&&d.status==='Open').forEach(d=>{d.status='Reviewed';d.reviewedAt=P.now()})}}P.audit(App.state,'Approval completed','Approval',a.id,prev,'Approved',`${a.type} · ${App.state.identity.name}`);await persist();render();toast(`${a.type} approval recorded.`)}
function controlPlanDefinitionResolver(cpId){const cp=App.state.controlPlans.find(c=>c.id===cpId);if(!cp){toast('Control Plan not found.',true);return}const invalid=(cp.characteristics||[]).filter(c=>c.classification&&!P.controlCharacteristicReady(c));if(!invalid.length){toast('Controlled definition is complete. Formal approval can now proceed.');render();return}const c=invalid[0];toast(`${invalid.length} controlled definition item${invalid.length===1?'':'s'} remaining. Opening ${c.characteristic||c.id}.`);editCpCharacteristic(cp.id,c.id)}
async function editControlPlan(cpId){let cp=App.state.controlPlans.find(c=>c.id===cpId);if(!cp)return;const r=requestById(App.workspaceId);if(cp.status==='Approved'&&r){cp=P.beginBuildSpecificControlPlanRevision(App.state,r,cp,'Control Plan adapted for this build');await persist();toast(`Approved master ${cp.baselineId} remains valid. Editing build-specific Draft ${cp.revision}.`)}else if(cp.status==='Approved'){cp=new P.ControlPlanService(App.state).revise(cpId);await persist()}controlPlanEditor(cp.id)}
function controlPlanEditor(cpId){const cp=App.state.controlPlans.find(c=>c.id===cpId);if(!cp)return;const rows=(cp.characteristics||[]).map(c=>`<div class="cp-edit-row"><div><strong>${esc(c.id)} · ${esc(c.characteristic)}</strong><span>${esc(c.classification||'Normal')} · ${P.controlCharacteristicReady(c)?'definition complete':'definition incomplete'}</span></div><div>${btn('Edit',`data-cpm-edit="${c.id}"`,'button tiny secondary')} ${btn('Remove',`data-cpm-remove="${c.id}"`,'button tiny danger')}</div></div>`).join('');openModal(`Edit Control Plan · Rev ${cp.revision}`,`<div class="form-grid"><div class="field"><label>Name</label><input id="cpmName" value="${esc(cp.name)}"></div><div class="field"><label>Phase</label><select id="cpmPhase"><option ${cp.phase==='Prototype'?'selected':''}>Prototype</option><option ${cp.phase==='Pre-launch / Safe Launch'?'selected':''}>Pre-launch / Safe Launch</option><option ${cp.phase==='Production reference'?'selected':''}>Production reference</option></select></div></div><div class="section-title-row" style="margin-top:14px"><div><h3>Characteristics</h3><div class="subtle">Add only what is needed for the selected build purpose.</div></div>${btn('+ Add characteristic','data-cpm-add','button small primary')}</div><div class="cp-edit-list">${rows||'<div class="empty">No characteristics yet.</div>'}</div>`,`${btn('Close','data-modal-close','button')}${btn('Save header','data-cpm-save','button primary')}`,true);setTimeout(()=>{const save=$('[data-cpm-save]');if(save)save.onclick=async()=>{const prev=cp.name;cp.name=$('#cpmName').value.trim()||cp.name;cp.phase=$('#cpmPhase').value;cp.status='Draft';P.audit(App.state,'Control Plan header edited','Control Plan',cp.id,prev,cp.name,`Rev ${cp.revision}`);await persist();closeModal();render();toast('Control Plan saved.')};$$('[data-cpm-edit]').forEach(el=>el.onclick=()=>editCpCharacteristic(cp.id,el.dataset.cpmEdit));$$('[data-cpm-remove]').forEach(el=>el.onclick=async()=>{const c=cp.characteristics.find(x=>x.id===el.dataset.cpmRemove);cp.characteristics=cp.characteristics.filter(x=>x.id!==el.dataset.cpmRemove);P.audit(App.state,'Control Plan characteristic removed','Control Plan',cp.id,c?.id||'Characteristic','Removed','Draft revision edit');await persist();controlPlanEditor(cp.id)});const add=$('[data-cpm-add]');if(add)add.onclick=()=>addCpCharacteristic(cp.id)},0)}
function addCpCharacteristic(cpId){const cp=App.state.controlPlans.find(c=>c.id===cpId);openModal('Add Control Plan characteristic',`<div class="form-grid"><div class="field"><label>Characteristic ID</label><input id="newCpId" value="CHAR-${cp.characteristics.length+1}"></div><div class="field"><label>Characteristic</label><input id="newCpName" placeholder="e.g. Leak rate"></div><div class="field"><label>Classification</label><select id="newCpClass"><option value="">Normal</option><option>SC</option><option>PS</option></select></div><div class="field"><label>Process step number</label><input id="newCpStep" type="number" min="1" value="1"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Add & define','data-save-new-cp-char','button primary')}`);setTimeout(()=>{$('[data-save-new-cp-char]').onclick=async()=>{const name=$('#newCpName').value.trim();if(!name){toast('Characteristic name is required.',true);return}const c={id:$('#newCpId').value.trim()||P.uid('CHAR'),processStep:Number($('#newCpStep').value||1),characteristic:name,classification:$('#newCpClass').value,target:null,lsl:null,usl:null,unit:'',method:'',equipment:'',sampleSize:'100%',frequency:'Each unit',controlMethod:'Recorded result',role:'Technician',reactionPlan:'',evidence:''};cp.characteristics.push(c);cp.status='Draft';P.audit(App.state,'Control Plan characteristic added','Control Plan',cp.id,'—',c.id,name);await persist();editCpCharacteristic(cp.id,c.id)}},0)}
function editCpCharacteristic(cpId,charId){const cp=App.state.controlPlans.find(c=>c.id===cpId),c=cp?.characteristics.find(x=>x.id===charId);if(!cp||!c){toast('Control Plan characteristic not found.',true);return}if(['Approved','Superseded'].includes(cp.status)){toast('Approved/superseded Control Plans cannot be edited. Create a new controlled revision.',true);return}openModal(`Control Plan · ${c.id}`,`<div class="callout"><h3>${esc(c.characteristic)}</h3><p>For a special characteristic, a target is optional when lower and/or upper limits already define the specification.</p></div><div style="height:12px"></div><div class="form-grid"><div class="field"><label>Target / nominal <small>(optional if limits define spec)</small></label><input id="cpTarget" value="${esc(c.target==='Define target'?'':c.target||'')}"></div><div class="field"><label>Unit</label><input id="cpUnit" value="${esc(c.unit||'')}"></div><div class="field"><label>Lower limit</label><input id="cpLsl" type="number" step="any" value="${c.lsl??''}"></div><div class="field"><label>Upper limit</label><input id="cpUsl" type="number" step="any" value="${c.usl??''}"></div><div class="field"><label>Measurement / test method</label><input id="cpMethod" value="${esc(c.method||'')}"></div><div class="field"><label>Gauge / equipment</label><select id="cpEquipment"><option value="">Select…</option>${App.state.equipment.map(e=>`<option value="${e.id}" ${c.equipment===e.id?'selected':''}>${esc(e.id)} · ${esc(e.name)} · ${esc(e.calibrationStatus)}</option>`).join('')}</select></div><div class="field"><label>Sample size</label><input id="cpSample" value="${esc(c.sampleSize||'100%')}"></div><div class="field"><label>Frequency</label><input id="cpFrequency" value="${esc(c.frequency||'Each unit')}"></div><div class="field full"><label>Reaction plan</label><textarea id="cpReaction">${esc(c.reactionPlan||'')}</textarea></div><div class="field full"><label>Record / evidence required</label><input id="cpEvidence" value="${esc(c.evidence||'')}"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save controlled definition','data-save-cp-char','button primary')}`,true);setTimeout(()=>{$('[data-save-cp-char]').onclick=async()=>{const target=$('#cpTarget').value.trim(),lsl=$('#cpLsl').value===''?null:Number($('#cpLsl').value),usl=$('#cpUsl').value===''?null:Number($('#cpUsl').value),method=$('#cpMethod').value.trim(),reaction=$('#cpReaction').value.trim(),equipment=$('#cpEquipment').value,evidence=$('#cpEvidence').value.trim(),hasSpec=!!target||lsl!==null||usl!==null;if(c.classification&&(!hasSpec||!method||!reaction||!equipment||!evidence)){toast('Special characteristic needs target OR limit(s), method/gauge, reaction plan and retained evidence.',true);return}const prev={target:c.target,lsl:c.lsl,usl:c.usl,method:c.method,equipment:c.equipment,reactionPlan:c.reactionPlan,evidence:c.evidence};c.target=target;c.unit=$('#cpUnit').value.trim();c.lsl=lsl;c.usl=usl;c.method=method;c.equipment=equipment;c.sampleSize=$('#cpSample').value.trim()||'100%';c.frequency=$('#cpFrequency').value.trim()||'Each unit';c.reactionPlan=reaction;c.evidence=evidence;cp.status='Draft';P.audit(App.state,'Control Plan characteristic updated','Control Plan',cp.id,JSON.stringify(prev),`${c.id} controlled definition updated`,`Draft revision ${cp.revision}`);await persist();closeModal();render();toast(P.controlCharacteristicReady(c)?'Control saved. This characteristic is definition-complete.':'Control saved; additional definition is still required.',!P.controlCharacteristicReady(c))}},0)}
function overrideModal(id){openModal('Controlled override',`<div class="form-grid"><div class="field"><label>Scope</label><input id="ovScope" value="Build readiness gate"></div><div class="field"><label>Temporary / permanent</label><select id="ovTemp"><option>Temporary</option><option>Permanent</option></select></div><div class="field full"><label>Reason</label><textarea id="ovReason" placeholder="Why is an override necessary?"></textarea></div><div class="field full"><label>Risk / impact</label><textarea id="ovRisk" placeholder="Describe quality, safety, delivery and traceability impact."></textarea></div><div class="field"><label>Approval required?</label><select id="ovApproval"><option value="true">Yes</option><option value="false">No</option></select></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Authorise override',`data-confirm-override="${id}"`,'button danger')}`);setTimeout(()=>{$('[data-confirm-override]').onclick=async()=>{try{new P.ReadinessService(App.state).override(id,$('#ovScope').value,$('#ovReason').value,$('#ovRisk').value,$('#ovTemp').value,$('#ovApproval').value==='true');await persist();closeModal();render();toast('Controlled override recorded in audit history.')}catch(e){toast(e.message,true)}}},0)}
async function generateSerials(id){try{const r=requestById(id),svc=new P.SerialService(App.state),before=samplesForRequest(id).length,out=svc.allocateRequested(id),after=samplesForRequest(id).length,target=r.materialOutputLimit&&Number.isFinite(Number(r.materialOutputLimit.maxBuildQty))?Math.min(Number(r.quantity||0),Math.max(0,Number(r.materialOutputLimit.maxBuildQty))):Number(r.quantity||0);if(!out.length){toast(target<Number(r.quantity||0)?`Sample register already matches the current material-supported output (${target}/${r.quantity}).`:`Sample register already matches requested quantity (${r.quantity}).`);return}await persist();render();toast(`${out.length} sample record(s) created. ${after}/${target} currently supported sample(s) are registered${target<Number(r.quantity||0)?` · request ${r.quantity}`:''}.`)}catch(e){toast(e.message,true)}}
function editSampleRegisterModal(requestId){const r=requestById(requestId),profile=P.ensureAssuranceProfile(r),samples=samplesForRequest(requestId);openModal('Edit sample register',`<div class="callout"><h3>Stable identity, editable labels</h3><p>The Lab Sample ID is permanent and is what measurements/process history use internally. You may change the human-facing sample number. Formal serial numbers are ${profile.requires.serialisation?'mandatory for this V/P build':'optional for this E0/E1 build'}.</p></div><div class="sample-edit-list" style="margin-top:12px">${samples.map((sm,i)=>`<div class="sample-edit-row"><div><b>${esc(sm.sampleId||sm.serial)}</b><small>Internal traceability ID</small></div><div class="field"><label>Sample number</label><input data-sample-number="${esc(sm.serial)}" value="${esc(sm.sampleNumber||String(i+1).padStart(2,'0'))}"></div><div class="field"><label>Formal serial ${profile.requires.serialisation?'':'(optional)'}</label><input data-sample-serial="${esc(sm.serial)}" value="${esc(sm.serialNumber||'')}"></div></div>`).join('')}</div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save sample register','data-save-sample-register','button primary')}`,true);setTimeout(()=>{$('[data-save-sample-register]').onclick=async()=>{const nums=new Set(),serials=new Set();for(const sm of samples){const n=$(`[data-sample-number="${sm.serial}"]`).value.trim(),sn=$(`[data-sample-serial="${sm.serial}"]`).value.trim();if(!n){toast('Every sample needs a sample number.',true);return}if(nums.has(n)){toast(`Duplicate sample number: ${n}`,true);return}nums.add(n);if(profile.requires.serialisation&&!sn){toast(`Formal serial number is required for sample ${n}.`,true);return}if(sn){if(serials.has(sn)){toast(`Duplicate formal serial number: ${sn}`,true);return}serials.add(sn)}}const before=JSON.stringify(samples.map(x=>({id:x.serial,sampleNumber:x.sampleNumber,serialNumber:x.serialNumber})));for(const sm of samples){sm.sampleNumber=$(`[data-sample-number="${sm.serial}"]`).value.trim();sm.serialNumber=$(`[data-sample-serial="${sm.serial}"]`).value.trim()}const after=JSON.stringify(samples.map(x=>({id:x.serial,sampleNumber:x.sampleNumber,serialNumber:x.serialNumber})));if(before!==after)P.invalidateBuildReport(App.state,r,'Sample number or formal serial changed');P.audit(App.state,'Sample register edited','Request',requestId,before,after,'Human-facing sample/serial labels updated; internal Lab Sample IDs unchanged');await persist();closeModal();render();toast('Sample register updated without breaking measurement/process links.')}},0)}
function editSingleSampleModal(sampleRef){const sm=(App.state.serials||[]).find(x=>x.serial===sampleRef);if(!sm)return;editSampleRegisterModal(sm.requestId)}
function sampleEvidenceModal(sampleRef){const sm=(App.state.serials||[]).find(x=>x.serial===sampleRef);if(!sm)return;const r=requestById(sm.requestId);P.syncRequestFlowdown(App.state,r);P.ensureSampleEvidence(sm);P.ensureSampleCaptureFields(sm,r);const approval=P.ensureBuildReportApproval(App.state,r),lockedWarning=approval.status==='Approved'?`<div class="callout warn"><h3>Final report protection</h3><p>This Build Report is currently FINAL. Saving changed sample evidence will create the next Build Report revision and require controlled approval again. The already-approved revision remains historical.</p></div>`:'';const photos=sm.evidencePhotos.map(ph=>`<div class="sample-photo-edit" data-photo-id="${esc(ph.id)}"><img src="${ph.dataUrl}" alt="${esc(ph.caption||'Sample photo')}"><div class="field"><label>Caption</label><input data-photo-caption value="${esc(ph.caption||'')}"></div><div class="field"><label>Description / observation</label><textarea data-photo-description>${esc(ph.description||'')}</textarea></div><div class="sample-photo-meta"><label class="check-line"><input type="checkbox" data-photo-report ${ph.includeInBuildReport!==false?'checked':''}> Include in Build Report</label><label class="check-line danger-text"><input type="checkbox" data-photo-remove> Remove photo</label><small>${esc(ph.fileName||'Photo')} · ${esc(ph.capturedBy||'')} ${ph.capturedAt?'· '+P.formatDateTime(ph.capturedAt):''}</small></div></div>`).join('');openModal(`Sample evidence · ${sampleLabel(sm)}`,`${lockedWarning}<div class="callout"><h3>One physical sample, one evidence record</h3><p>Structured data, descriptions and photos stay tied to <strong>${esc(sm.sampleId||sm.serial)}</strong>. Select exactly what should appear in the Build Report.</p></div><div class="field" style="margin-top:12px"><label>Sample description / build observation</label><textarea id="sampleDescription" placeholder="Describe this sample, condition, configuration, visual observations or notable build details.">${esc(sm.description||'')}</textarea><label class="check-line"><input id="sampleDescriptionReport" type="checkbox" ${sm.includeDescriptionInBuildReport!==false?'checked':''}> Include description in Build Report</label></div><div class="section-title-row" style="margin-top:16px"><div><h3>Structured sample data</h3><div class="subtle">Use this for per-sample values that are not already controlled measurement characteristics.</div></div>${btn('+ Data field','data-add-sample-data-row','button small secondary')}</div><div id="sampleDataRows" class="sample-data-edit-list">${sm.dataFields.map(sampleDataRowHtml).join('')||sampleDataRowHtml({includeInBuildReport:true})}</div><div class="section-title-row" style="margin-top:16px"><div><h3>Photos</h3><div class="subtle">Photos are resized to max 1600 px and compressed before local storage to keep the POC responsive.</div></div><span class="pill">${sm.evidencePhotos.length} stored</span></div><div class="sample-photo-edit-grid">${photos||'<div class="empty">No photos stored for this sample yet.</div>'}</div><div class="card sample-new-photo"><h3>Add photo</h3><div class="form-grid"><div class="field full"><label>Take / choose photo</label><input id="samplePhotoFile" type="file" accept="image/*" capture="environment"><small>On a phone this can open the camera directly. Maximum input size 15 MB.</small></div><div class="field"><label>Caption</label><input id="samplePhotoCaption" placeholder="e.g. Connector after crimp"></div><div class="field"><label>Photo observation</label><input id="samplePhotoDescription" placeholder="Optional detail"></div><label class="check-line"><input id="samplePhotoReport" type="checkbox" checked> Include new photo in Build Report</label></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save sample evidence','data-save-sample-evidence','button primary')}`,true);setTimeout(()=>{const root=$('#sampleDataRows'),add=$('[data-add-sample-data-row]');const bindRemove=()=>$$('[data-remove-sample-data-row]',root).forEach(el=>el.onclick=()=>{const rows=$$('[data-sample-data-row]',root);if(rows.length===1){const row=el.closest('[data-sample-data-row]');row.querySelector('[data-sd-label]').value='';row.querySelector('[data-sd-value]').value='';row.querySelector('[data-sd-unit]').value='';row.querySelector('[data-sd-desc]').value='';return}el.closest('[data-sample-data-row]')?.remove()});if(add)add.onclick=()=>{root.insertAdjacentHTML('beforeend',sampleDataRowHtml({includeInBuildReport:true}));bindRemove()};bindRemove();$('[data-save-sample-evidence]').onclick=async()=>{try{const old=JSON.stringify({description:sm.description,dataFields:sm.dataFields,evidencePhotos:sm.evidencePhotos.map(x=>({id:x.id,caption:x.caption,description:x.description,includeInBuildReport:x.includeInBuildReport,dataUrl:x.dataUrl}))});const dataFields=$$('[data-sample-data-row]',root).map(row=>({id:row.dataset.rowId||P.uid('SDATA'),definitionId:row.dataset.definitionId||null,definitionActive:!!row.dataset.definitionId,label:row.querySelector('[data-sd-label]').value.trim(),value:row.querySelector('[data-sd-value]').value.trim(),unit:row.querySelector('[data-sd-unit]').value.trim(),description:row.querySelector('[data-sd-desc]').value.trim(),includeInBuildReport:row.querySelector('[data-sd-report]').checked})).filter(x=>x.label||x.value||x.description);const existing=[];$$('[data-photo-id]').forEach(card=>{const ph=sm.evidencePhotos.find(x=>x.id===card.dataset.photoId);if(!ph||card.querySelector('[data-photo-remove]').checked)return;existing.push({...ph,caption:card.querySelector('[data-photo-caption]').value.trim()||ph.fileName||'Sample photo',description:card.querySelector('[data-photo-description]').value.trim(),includeInBuildReport:card.querySelector('[data-photo-report]').checked})});const file=$('#samplePhotoFile').files?.[0];if(file){const img=await compressSamplePhoto(file);existing.push({id:P.uid('PHOTO'),fileName:file.name,fileType:'image/jpeg',dataUrl:img.dataUrl,width:img.width,height:img.height,caption:$('#samplePhotoCaption').value.trim()||file.name,description:$('#samplePhotoDescription').value.trim(),includeInBuildReport:$('#samplePhotoReport').checked,capturedAt:P.now(),capturedBy:App.state.identity.name})}sm.description=$('#sampleDescription').value.trim();sm.includeDescriptionInBuildReport=$('#sampleDescriptionReport').checked;sm.dataFields=dataFields;sm.evidencePhotos=existing;P.ensureSampleEvidence(sm);const now=JSON.stringify({description:sm.description,dataFields:sm.dataFields,evidencePhotos:sm.evidencePhotos.map(x=>({id:x.id,caption:x.caption,description:x.description,includeInBuildReport:x.includeInBuildReport,dataUrl:x.dataUrl}))});if(old!==now){P.invalidateBuildReport(App.state,r,'Sample-specific description, data or photo evidence changed');P.audit(App.state,'Sample evidence updated','Sample',sm.sampleId||sm.serial,'Previous sample evidence',`${sm.dataFields.length} data field(s) · ${sm.evidencePhotos.length} photo(s)`,`Request ${sm.requestId}; Build Report inclusion controlled per evidence item`)}await persist();closeModal();render();toast(file?'Sample evidence and photo saved.':'Sample evidence saved.')}catch(e){toast(e.message||'Could not save sample evidence.',true)}}},0)}
