function bindWizard(){const back=$('[data-w-back]'),next=$('[data-w-next]'),create=$('[data-w-create]'),src=$('#wMatOwn'),purpose=$('#wPurpose'),assurance=$('#wAssurance');if(purpose&&assurance){purpose.onchange=()=>{const rec=P.recommendAssuranceProfile({...App.wizardData,purpose:purpose.value});assurance.value=rec;const h=$('#wAssuranceHint'),p=P.ASSURANCE_PROFILES[rec];if(h)h.textContent=`Recommended from purpose: ${p.code} · ${p.label}. You can deliberately select a different level; Product Safety enforces at least Validation.`}};if(src)src.onchange=()=>{$('#wEngSupply')?.classList.toggle('hidden',src.value!=='Engineering supplied')};if(back)back.onclick=()=>{captureWizard();App.wizardStep--;renderWizard()};if(next)next.onclick=()=>{captureWizard();if(App.wizardStep===0&&(!App.wizardData.title||App.wizardData.quantity<1)){toast('Add a request title and quantity.',true);return}App.wizardStep++;renderWizard()};if(create)create.onclick=async()=>{const req=new P.RequestService(App.state).create(App.wizardData);P.syncRequestFlowdown(App.state,req);await persist();closeModal();openRequest(req.id);toast('Draft prototype request created.')}}
