function importJson(){const i=document.createElement('input');i.type='file';i.accept='.json,application/json';i.onchange=async()=>{try{const txt=await i.files[0].text();App.state=await App.repo.importJSON(txt);App.identity=new P.DemoIdentityProvider(App.state);populateRoles();await persist();nav('dashboard');toast('JSON imported and migrated to current schema.')}catch(e){toast(`Import failed: ${e.message}`,true)}};i.click()}
async function resetDemo(){if(!confirm('Reset all local POC data to seeded demo state?'))return;App.state=await App.repo.reset();App.identity=new P.DemoIdentityProvider(App.state);populateRoles();nav('dashboard');toast('Demo data reset.')}
function renderSearch(q){q=q.trim().toLowerCase();const root=$('#searchResults');if(q.length<2){root.classList.add('hidden');return}const res=[];App.state.products.forEach(p=>{if([p.id,p.family,p.partNumber,p.revision,p.hw,p.sw].join(' ').toLowerCase().includes(q))res.push({type:'Product',id:p.id,label:`${p.family} · ${p.partNumber}`,sub:`${p.id} · Rev ${p.revision}`})});App.state.requests.forEach(r=>{if([r.id,r.title,r.productFamily,r.customerId,r.engineeringTeam].join(' ').toLowerCase().includes(q))res.push({type:'Request',id:r.id,label:`${r.id} · ${r.title}`,sub:r.productFamily})});App.state.serials.forEach(s=>{if([s.serial,s.sampleNumber,s.serialNumber].join(' ').toLowerCase().includes(q))res.push({type:'Serial',id:s.serial,label:`Sample ${s.sampleNumber||'—'} · ${s.sampleId||s.serial}${s.serialNumber?' · SN '+s.serialNumber:''}`,sub:s.requestId})});App.state.processes.forEach(p=>{if([p.id,p.name].join(' ').toLowerCase().includes(q))res.push({type:'Process',id:p.id,label:`${p.id} · ${p.name}`,sub:`Rev ${p.revision} · ${p.status}`})});App.state.materials.forEach(m=>{if([m.partNumber,m.lot,m.description].join(' ').toLowerCase().includes(q))res.push({type:'Material',id:m.id,label:`${m.partNumber} · ${m.lot}`,sub:m.description})});App.state.deviations.forEach(d=>{if([d.id,d.requestId,d.serial,d.measurement].join(' ').toLowerCase().includes(q))res.push({type:'Deviation',id:d.id,label:`${d.id} · ${d.measurement}`,sub:d.requestId})});root.innerHTML=res.slice(0,10).map((x,i)=>`<button class="search-result" data-search-index="${i}"><strong>${esc(x.label)}</strong><small>${esc(x.type)} · ${esc(x.sub)}</small></button>`).join('')||'<div class="empty">No matching controlled record.</div>';root.classList.remove('hidden');$$('[data-search-index]',root).forEach((el,i)=>el.onclick=()=>{const x=res[i];root.classList.add('hidden');if(x.type==='Product'){nav('products');setTimeout(()=>document.querySelector(`[data-edit-product=\"${x.id}\"]`)?.scrollIntoView({behavior:'smooth',block:'center'}),0)}else if(x.type==='Request')openRequest(x.id);else if(x.type==='Serial')showSerial(x.id);else if(x.type==='Process')showProcess(x.id);else if(x.type==='Deviation'){const d=App.state.deviations.find(d=>d.id===x.id);openRequest(d.requestId,'quality')}else toast(`${x.type}: ${x.label}`)})}

/* REV 1.0.56 enhancement layer: MSA, governed setup dossiers, guided resolution,
   controlled exceptions, learning capture, process skipping and fast section navigation. */
const _guidedNextDock1055=guidedNextDock;
guidedNextDock=function(r,steps,step){return _guidedNextDock1055(r,steps,step).replace(/button small primary workflow-dock-button/g,'button small next-action workflow-dock-button').replace(/button small workflow-dock-button" type="button" disabled/g,'button small next-action workflow-dock-button" type="button" disabled')};

const _sampleLabel1055=sampleLabel;
sampleLabel=function(s){if(!s)return 'Build-level';const lab=s.sampleId||s.serial||'',formal=s.serialNumber&&s.serialNumber!==lab?s.serialNumber:'';return `Sample ${s.sampleNumber||'—'}${lab?` · ${lab}`:''}${formal?` · SN ${formal}`:''}`};
sampleDisplayFromRef=function(requestId,ref){const s=sampleByRef(requestId,ref);if(!s)return ref||'Build-level';const lab=s.sampleId||s.serial||'',formal=s.serialNumber&&s.serialNumber!==lab?s.serialNumber:'';return `#${s.sampleNumber||'—'}${lab?` · ${lab}`:''}${formal?` · SN ${formal}`:''}`};
const _stepDoneForSample1055=stepDoneForSample;
stepDoneForSample=function(step,sample){return step?.skipStatus==='Approved'||_stepDoneForSample1055(step,sample)};

function governanceObject(kind,id){if(kind==='process')return App.state.processes.find(x=>x.id===id);if(kind==='test')return (App.state.standardTests||[]).find(x=>x.id===id);if(kind==='equipment')return (App.state.equipment||[]).find(x=>x.id===id);return null}
function governanceKindLabel(kind){return kind==='process'?'Process':kind==='test'?'Standard test':'Equipment / setup'}
function documentEvidenceText(d){if(!d)return 'Missing';return [d.reference,d.fileName,d.description].filter(Boolean).join(' · ')||'No evidence reference'}
function governanceCanApprove(kind){const role=currentRole();return role==='administrator'||role==='approver'||role==='quality'||role==='lab_manager'||(kind==='equipment'&&role==='metrology')||(['process','test'].includes(kind)&&role==='process_engineer')}
function controlledDocStatus(d){return P.controlledDocumentApproved?.(d)?'<span class="status good">✓ Approved</span>':`<span class="status ${d?.status==='Rejected'?'bad':'warn'}">● ${esc(d?.status||'Draft')}</span>`}
async function updateControlledDocFromInputs(obj,key,prefix){const d=obj[key]||(obj[key]={id:`${prefix.toUpperCase()}-${obj.id}`,revision:'A'}),ref=$(`#${prefix}Ref`)?.value?.trim()||'',desc=$(`#${prefix}Desc`)?.value?.trim()||'',file=$(`#${prefix}File`)?.files?.[0]||null,before=JSON.stringify({reference:d.reference,description:d.description,fileName:d.fileName,status:d.status});d.reference=ref;d.description=desc;if(file){d.fileData=await readFileDataUrl(file);d.fileName=file.name;d.fileType=file.type;d.fileSize=file.size;d.documentUploaded=true}const after=JSON.stringify({reference:d.reference,description:d.description,fileName:d.fileName,status:d.status});if(before!==after){d.status='Draft';d.approvedBy='';d.approvedAt=null;d.approvalRationale='';d.updatedBy=App.state.identity.name;d.updatedAt=P.now()}return d}
function governanceDocsModal(kind,id){const obj=governanceObject(kind,id);if(!obj)return;P.ensureEnterpriseModel(App.state);const ehs=obj.ehsRiskAssessment||{},comm=obj.commissioningDocument||{},inhouse=kind==='equipment'&&obj.calibrationMode==='In-house',proc=obj.calibrationProcedure||{};const docBlock=(label,d,prefix,help)=>`<div class="controlled-doc-editor"><div class="section-title-row"><div><strong>${esc(label)}</strong><small>${esc(help)}</small></div>${controlledDocStatus(d)}</div><div class="form-grid"><div class="field"><label>Controlled reference</label><input id="${prefix}Ref" value="${esc(d.reference||'')}" placeholder="Document / QMS / SharePoint reference"></div><div class="field"><label>Upload / replace document</label><input id="${prefix}File" type="file" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png,.txt"></div><div class="field full"><label>Description / scope</label><textarea id="${prefix}Desc" placeholder="What is assessed/released, boundaries and relevant conditions">${esc(d.description||'')}</textarea></div></div>${d.approvedBy?`<small>Approved by ${esc(d.approvedBy)} · ${P.formatDateTime(d.approvedAt)}</small>`:''}</div>`;const body=`<div class="callout"><h3>Controlled setup dossier</h3><p>Work instructions remain the executable operator document. EHS risk assessment and commissioning/release evidence are separate controlled records and stay linked to this exact ${esc(governanceKindLabel(kind).toLowerCase())}.</p></div>${kind!=='equipment'&&obj.workInstruction?`<div class="score-row"><span><strong>Work instruction</strong><small>${esc(obj.workInstruction.id||'WI')} · Rev ${esc(obj.workInstruction.revision||'A')}</small></span>${status(obj.workInstruction.status||'Draft')}</div>`:''}<div style="height:10px"></div>${docBlock('EHS risk assessment',ehs,'ehs','Hazards, controls, residual risk and operating boundaries.')}${docBlock(kind==='equipment'?'Setup release / commissioning':'Release / commissioning',comm,'comm','Objective evidence that the setup/process is commissioned and released for controlled use.')}${kind==='equipment'?`<div class="card compact" style="margin-top:12px"><div class="field"><label>Calibration route</label><select id="calMode"><option ${obj.calibrationMode==='External'?'selected':''}>External</option><option ${obj.calibrationMode==='Internal service'?'selected':''}>Internal service</option><option ${obj.calibrationMode==='In-house'?'selected':''}>In-house</option></select></div><small>In-house calibration requires an approved calibration procedure before the asset can be readiness-valid.</small></div><div id="calProcedureWrap" style="margin-top:12px;${inhouse?'':'display:none'}">${docBlock('In-house calibration procedure',proc,'calproc','Method, standards, environmental conditions, calculation/acceptance criteria and record requirements.')}</div>`:''}`;const footer=`${btn('Close','data-modal-close','button')}${currentRole()==='administrator'?btn('Administrator exception…',`data-admin-exception="${governanceKindLabel(kind)==='Equipment / setup'?'Equipment':governanceKindLabel(kind)}|${id}|${kind==='equipment'?'Equipment governance':'Process governance'}"`,'button admin-exception'):''}${btn('Save dossier','data-save-governance-docs','button secondary')}${governanceCanApprove(kind)?btn('Review & approve','data-approve-governance-docs','button next-action'):''}`;openModal(`${governanceKindLabel(kind)} dossier · ${obj.name||obj.id}`,body,footer,true);setTimeout(()=>{const mode=$('#calMode'),wrap=$('#calProcedureWrap');if(mode&&wrap)mode.onchange=()=>wrap.style.display=mode.value==='In-house'?'block':'none';const save=$('[data-save-governance-docs]');if(save)save.onclick=async()=>{if(kind==='equipment')obj.calibrationMode=$('#calMode').value;await updateControlledDocFromInputs(obj,'ehsRiskAssessment','ehs');await updateControlledDocFromInputs(obj,'commissioningDocument','comm');if(kind==='equipment'&&obj.calibrationMode==='In-house')await updateControlledDocFromInputs(obj,'calibrationProcedure','calproc');P.audit(App.state,'Controlled setup dossier updated',governanceKindLabel(kind),id,'Previous controlled evidence','Draft / updated',App.state.identity.name);await persist();closeModal();render();toast('Dossier saved. Changed documents require controlled approval.');};const approve=$('[data-approve-governance-docs]');if(approve)approve.onclick=async()=>{if(kind==='equipment')obj.calibrationMode=$('#calMode').value;await updateControlledDocFromInputs(obj,'ehsRiskAssessment','ehs');await updateControlledDocFromInputs(obj,'commissioningDocument','comm');if(kind==='equipment'&&obj.calibrationMode==='In-house')await updateControlledDocFromInputs(obj,'calibrationProcedure','calproc');const docs=[obj.ehsRiskAssessment,obj.commissioningDocument,...(kind==='equipment'&&obj.calibrationMode==='In-house'?[obj.calibrationProcedure]:[])];const missing=docs.filter(d=>!(String(d.reference||'').trim()||d.fileData||String(d.description||'').trim()));if(missing.length){toast('Each controlled document needs a reference, upload or substantive description before approval.',true);return}const now=P.now();docs.forEach(d=>{d.status='Approved';d.approvedBy=App.state.identity.name;d.approvedAt=now;d.approvalRationale='Controlled dossier reviewed and approved for intended use.'});if(kind==='equipment'){obj.calibrationCertificateValid=!!P.validCalibrationCertificate(App.state,obj.id,P.todayISO())}P.audit(App.state,'Controlled setup dossier approved',governanceKindLabel(kind),id,'Draft','Approved',`${App.state.identity.name} · EHS / commissioning${kind==='equipment'&&obj.calibrationMode==='In-house'?' / calibration procedure':''}`);await persist();closeModal();render();toast('Controlled setup dossier approved.');};$$('[data-admin-exception]',$('#modalRoot')).forEach(b=>b.onclick=()=>{const [scopeType,scopeId,condition]=b.dataset.adminException.split('|');closeModal();adminExceptionModal(scopeType,scopeId,condition)});},0)}

function governanceRegister(kind){const items=kind==='equipment'?(App.state.equipment||[]):[...(App.state.processes||[]).map(x=>({...x,_kind:'process'})),...(App.state.standardTests||[]).map(x=>({...x,_kind:'test'}))];if(!items.length)return '';const rows=items.map(x=>{const k=kind==='equipment'?'equipment':x._kind,source=governanceObject(k,x.id)||x,assess=k==='equipment'?P.equipmentGovernanceAssessment(source):P.processGovernanceAssessment(source),extra=k==='equipment'?` · calibration ${esc(source.calibrationMode||'External')}`:` · WI ${esc(source.workInstruction?.status||'Missing')}`;return `<tr><td><strong>${esc(source.name)}</strong><small>${esc(source.id)}${extra}</small></td><td>${controlledDocStatus(source.ehsRiskAssessment)}</td><td>${controlledDocStatus(source.commissioningDocument)}</td>${k==='equipment'?`<td>${source.calibrationMode==='In-house'?controlledDocStatus(source.calibrationProcedure):'<span class="status neutral">n/a</span>'}</td>`:''}<td>${assess.ready?'<span class="status good">✓ Ready</span>':'<span class="status bad">✕ Incomplete</span>'}</td><td>${btn('Open dossier',`data-governance-docs="${k}|${source.id}"`,'button tiny secondary')}</td></tr>`}).join('');return `<div class="card governance-register"><div class="section-title-row"><div><span class="eyebrow">CONTROLLED SETUP DOSSIERS</span><h2>${kind==='equipment'?'Equipment EHS, commissioning & calibration procedures':'Process / test EHS, commissioning & work-instruction governance'}</h2><div class="subtle">The work instruction says how to execute. The EHS assessment controls hazards. Commissioning/release evidence proves the setup is approved for controlled use.</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${kind==='equipment'?'Equipment':'Standard'}</th><th>EHS</th><th>Commissioning</th>${kind==='equipment'?'<th>In-house calibration procedure</th>':''}<th>Readiness</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></div>`}
const _renderProcessLibrary1055=renderProcessLibrary;
renderProcessLibrary=function(){return _renderProcessLibrary1055()+governanceRegister('standards')};
const _renderEquipmentMaster1055=renderEquipmentMaster;
renderEquipmentMaster=function(){return _renderEquipmentMaster1055()+`<div style="height:14px"></div>`+governanceRegister('equipment')};

const _releaseLibraryProcess1055=releaseLibraryProcess;
releaseLibraryProcess=async function(id){const p=App.state.processes.find(x=>x.id===id);if(!p)return;P.ensureEnterpriseModel(App.state);const coreOk=!!p.workInstruction?.steps?.length&&!!p.equipmentCapability&&!!p.competency&&Number.isFinite(Number(p.setupTime))&&Number.isFinite(Number(p.cycleTime)),gov=P.processGovernanceAssessment(p),exception=P.activeAdminException?.(App.state,'Process',id,'Process governance');if(!coreOk){toast('Cannot release: work instruction, planning time, equipment capability and certified skill are mandatory.',true);return}if(!gov.ready&&!exception){governanceDocsModal('process',id);toast(`Release dossier incomplete: ${gov.issues.join(', ')}.`,true);return}p.status='Released';p.workInstruction.status='Released';p.approvals=p.approvals||[];p.approvals.push({role:roleLabel(currentRole()),person:App.state.identity.name,date:P.todayISO(),exceptionId:exception?.id||null});P.audit(App.state,exception?'Process released under administrator exception':'Process released','Process',id,'Under review','Released',exception?`Exception ${exception.id}; unresolved governance remains visible`:'Controlled definition, work instruction, EHS and commissioning evidence complete');await persist();render();toast(exception?'Process released under controlled administrator exception.':'Process released and available for future routes.')};

function adminExceptionModal(scopeType,scopeId,condition='Lifecycle gate',after=null){if(currentRole()!=='administrator'){toast('Only Administrator may create a controlled exception.',true);return}const label=scopeType==='Build'?`${scopeId} · ${requestById(scopeId)?.title||''}`:`${scopeId} · ${governanceObject(scopeType==='Equipment'?'equipment':'process',scopeId)?.name||''}`;openModal(`Administrator exception · ${scopeType}`,`<div class="callout bad"><h3>Exception — not completion</h3><p>This permits controlled progression despite unresolved evidence. LabOS will retain the original deficiencies, exception ID, rationale, containment and approver in the audit record. Missing evidence does not turn green.</p></div><div class="score-row"><span>Scope</span><strong>${esc(label)}</strong></div><div class="score-row"><span>Condition being overridden</span><strong>${esc(condition||'Controlled blocker')}</strong></div><div class="form-grid" style="margin-top:12px"><div class="field full"><label>Reason / business justification <b>required</b></label><textarea id="exReason" placeholder="Why must work proceed before normal closure?"></textarea></div><div class="field full"><label>Risk / impact assessment <b>required</b></label><textarea id="exRisk" placeholder="What could go wrong because the normal gate is incomplete?"></textarea></div><div class="field full"><label>Containment / compensating controls <b>required</b></label><textarea id="exContain" placeholder="How is risk controlled while the exception is active?"></textarea></div><div class="field full"><label>Evidence / authorisation reference <b>required</b></label><input id="exEvidence" placeholder="Deviation / approval / meeting / document reference"></div><div class="field"><label>Expiry (optional)</label><input id="exExpiry" type="date"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Authorise controlled exception','data-save-admin-exception','button admin-exception')}`,true);setTimeout(()=>{$('[data-save-admin-exception]').onclick=async()=>{const reason=$('#exReason').value.trim(),risk=$('#exRisk').value.trim(),containment=$('#exContain').value.trim(),evidence=$('#exEvidence').value.trim();if(!reason||!risk||!containment||!evidence){toast('Reason, risk, containment and evidence are all required.',true);return}const rec={id:P.uid('EXC'),scopeType,scopeId,condition,status:'Active',reason,risk,containment,evidence,createdBy:App.state.identity.name,createdAt:P.now(),expiresAt:$('#exExpiry').value||null};App.state.adminExceptions=App.state.adminExceptions||[];App.state.adminExceptions.push(rec);P.audit(App.state,'Administrator exception authorised',scopeType,scopeId,condition,`Exception ${rec.id}`,`${reason} · Risk: ${risk} · Containment: ${containment} · Evidence: ${evidence}`);await persist();closeModal();render();toast(`Controlled exception ${rec.id} is active. Original blockers remain visible.`);if(typeof after==='function')after(rec)}},0)}

const _advanceGateModal1055=advanceGateModal;
advanceGateModal=function(id){const r=requestById(id);if(!r)return;const check=new P.LifecycleService(App.state).check(id);if(!check.next){toast(check.blockers?.[0]||'No later gate is available.',true);return}if(!check.ok){if(currentRole()==='administrator'){openModal(`Gate blocked · ${r.currentGate}`,`<div class="callout bad"><h3>${check.blockers.length} blocker${check.blockers.length===1?'':'s'}</h3><ul>${check.blockers.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><p>The normal route is to resolve the underlying evidence. An Administrator may instead create a controlled exception; the deficiencies stay visible and auditable.</p>`,`${btn('Cancel','data-modal-close','button')}${btn('Authorise exception & continue…','data-gate-admin-exception','button admin-exception')}`);setTimeout(()=>{$('[data-gate-admin-exception]').onclick=()=>{closeModal();adminExceptionModal('Build',id,'Lifecycle gate',()=>advanceGateModal(id))}},0);return}toast(check.blockers.join(' '),true);return}const exception=check.exception;openModal(`Gate review · ${r.currentGate} → ${check.next}`,`${exception?`<div class="callout warn"><h3>Administrator exception active · ${esc(exception.id)}</h3><p>${esc(exception.reason)}. Unresolved conditions remain recorded: ${esc((check.overriddenBlockers||[]).join(' · ')||'none at this gate')}.</p></div>`:''}<div class="callout"><h3>Objective gate review</h3><p>${exception?'Progression is authorised by a controlled exception. Record what evidence was still reviewed.':'Gate progression remains evidence-based. Record the review conclusion before advancing.'}</p></div><div style="height:12px"></div><div class="field"><label>Evidence / review conclusion <small>required</small></label><textarea id="gateEvidence"></textarea></div><div class="field" style="margin-top:12px"><label>Reason / decision note</label><input id="gateReason"></div>`,`${btn('Cancel','data-modal-close','button')}${btn(`Advance to ${check.next}`,`data-confirm-gate-v1056="${id}"`,'button next-action')}`);setTimeout(()=>{$('[data-confirm-gate-v1056]').onclick=async()=>{try{new P.LifecycleService(App.state).advance(id,{evidence:$('#gateEvidence').value.trim(),reason:$('#gateReason').value.trim()});await persist();closeModal();render();toast(`Gate advanced to ${r.currentGate}${exception?' under controlled exception':''}.`)}catch(e){toast(e.message,true)}}},0)};

function processSkipModal(requestId,stepId){const r=requestById(requestId),route=App.state.routes.find(x=>x.requestId===requestId),step=route?.steps?.find(x=>x.id===stepId);if(!r||!step)return;App.state.processSkipApprovals=App.state.processSkipApprovals||[];let rec=App.state.processSkipApprovals.find(x=>x.requestId===requestId&&x.stepId===stepId&&x.status==='Pending');if(step.skipStatus==='Approved'){const done=App.state.processSkipApprovals.find(x=>x.id===step.skipApprovalId);openModal(`Skipped · ${step.name}`,`<div class="callout warn"><h3>Approved process-step skip</h3><p>This operation was deliberately not executed. It is treated as lifecycle-complete only because an authorised approval is retained.</p></div><div class="score-row"><span>Reason</span><strong>${esc(done?.reason||'—')}</strong></div><div class="score-row"><span>Containment / impact</span><strong>${esc(done?.impact||'—')}</strong></div><div class="score-row"><span>Approved by</span><strong>${esc(done?.approvedBy||'—')} · ${P.formatDateTime(done?.approvedAt)}</strong></div>`,btn('Close','data-modal-close','button'));return}const approverRoles=[['process_engineer','Process Engineer'],['quality','Quality Engineer'],['lab_manager','Lab Manager'],['approver','Approver / Reviewer']];if(rec){const authorised=currentRole()==='administrator'||currentRole()===rec.approverRole;openModal(`Skip approval · ${step.name}`,`<div class="callout warn"><h3>Skip requested</h3><p><b>Reason:</b> ${esc(rec.reason)}</p><p><b>Impact / containment:</b> ${esc(rec.impact)}</p><p><b>Evidence:</b> ${esc(rec.evidence)}</p></div>${authorised?`<div class="field"><label>Approval / rejection rationale <b>required</b></label><textarea id="skipDecisionNote"></textarea></div>`:`<div class="callout"><p>Waiting for ${esc(roleLabel(rec.approverRole))}. Switch role to review this request.</p></div>`}`,`${btn('Close','data-modal-close','button')}${authorised?`${btn('Reject skip','data-skip-decision="Rejected"','button blocker-action')}${btn('Approve skip','data-skip-decision="Approved"','button next-action')}`:btn(`Switch to ${roleLabel(rec.approverRole)}`,`data-switch-role="${rec.approverRole}"`,'button secondary')}`);setTimeout(()=>{$$('[data-skip-decision]').forEach(b=>b.onclick=async()=>{const note=$('#skipDecisionNote').value.trim();if(!note){toast('Record the approval decision rationale.',true);return}rec.status=b.dataset.skipDecision;rec.decisionRationale=note;rec.approvedBy=App.state.identity.name;rec.approvedAt=P.now();if(rec.status==='Approved'){step.skipStatus='Approved';step.skipApprovalId=rec.id;step.status='Skipped';step.readiness='ready';P.invalidateBuildReport(App.state,r,`Route step skipped by approval · ${step.name}`)}P.audit(App.state,rec.status==='Approved'?'Process step skip approved':'Process step skip rejected','Route step',step.id,'Pending',rec.status,`${requestId} · ${note}`);await persist();closeModal();render();toast(rec.status==='Approved'?'Process step marked Skipped with approval.':'Skip request rejected.',rec.status!=='Approved')})},0);return}openModal(`Request process-step skip · ${step.name}`,`<div class="callout warn"><h3>Skipping is a controlled exception to execution</h3><p>The step is not deleted. It remains visible as <b>Skipped</b> together with the approval and rationale in history and the Build Report.</p></div><div class="form-grid"><div class="field full"><label>Why can this step be skipped? <b>required</b></label><textarea id="skipReason"></textarea></div><div class="field full"><label>Impact / containment <b>required</b></label><textarea id="skipImpact"></textarea></div><div class="field full"><label>Evidence / reference <b>required</b></label><input id="skipEvidence"></div><div class="field"><label>Approver</label><select id="skipApprover">${approverRoles.map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('')}</select></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Submit skip for approval','data-submit-skip','button next-action')}`);setTimeout(()=>{$('[data-submit-skip]').onclick=async()=>{const reason=$('#skipReason').value.trim(),impact=$('#skipImpact').value.trim(),evidence=$('#skipEvidence').value.trim();if(!reason||!impact||!evidence){toast('Reason, impact/containment and evidence are required.',true);return}rec={id:P.uid('SKIP'),requestId,stepId,stepName:step.name,status:'Pending',reason,impact,evidence,approverRole:$('#skipApprover').value,requestedBy:App.state.identity.name,requestedAt:P.now()};App.state.processSkipApprovals.push(rec);P.audit(App.state,'Process step skip requested','Route step',stepId,'Normal execution','Pending skip approval',`${requestId} · ${reason}`);await persist();closeModal();render();toast(`Skip request sent to ${roleLabel(rec.approverRole)}.`)}},0)}
const _workspaceExecution1055=workspaceExecution;
workspaceExecution=function(r){const html=_workspaceExecution1055(r),step=selectedExecutionStep(r);if(!step)return html;const rec=(App.state.processSkipApprovals||[]).find(x=>x.requestId===r.id&&x.stepId===step.id&&x.status==='Pending'),approved=step.skipStatus==='Approved';const panel=`<div class="card process-skip-control ${approved?'skip-approved':''}"><div class="section-title-row"><div><span class="eyebrow">CONTROLLED STEP EXCEPTION</span><h3>${approved?'This operation was skipped by approval':rec?'Skip approval pending':'Need to omit this operation?'}</h3><div class="subtle">The operation remains in the route and audit trail; skipping never silently deletes required work.</div></div>${approved?'<span class="status warn">● Skipped</span>':btn(rec?'Review skip request':'Request skip',`data-skip-step="${r.id}|${step.id}"`,rec?'button small next-action':'button small secondary')}</div></div>`;return html+panel};
const _processCard1055=processCard;
processCard=function(s,i){let html=_processCard1055(s,i);if(s.skipStatus==='Approved')html=html.replace(/workflow-(complete|blocked|current)/,'workflow-skipped').replace(/<div class="route-workflow-icon [^"]+">[^<]*<\/div>/,'<div class="route-workflow-icon skipped">↷</div>').replace(/<span>[^<]*(Done|Blocked|Ongoing \/ planned)[^<]*<\/span>/,'<span>Skipped · approved</span>');return html};

function editSampleRegisterModalV1056(requestId){const r=requestById(requestId),profile=P.ensureAssuranceProfile(r),samples=samplesForRequest(requestId);openModal('Sample identity register',`<div class="callout"><h3>Sample number is generated once</h3><p>The build sample number and permanent Lab Sample ID are automatic. You only enter a separate formal product serial when the assurance profile requires it. LabOS will not ask you to type the same identifier twice.</p></div><div class="sample-edit-list" style="margin-top:12px">${samples.map(sm=>{const formal=sm.serialNumber===sm.sampleId||sm.serialNumber===sm.serial?'':sm.serialNumber||'';return `<div class="sample-edit-row"><div><b>Sample ${esc(sm.sampleNumber||'—')}</b><small>${esc(sm.sampleId||sm.serial)} · permanent Lab ID</small></div><div class="field"><label>Formal serial ${profile.requires.serialisation?'':'(optional)'}</label><input data-v1056-sample-serial="${esc(sm.serial)}" value="${esc(formal)}" placeholder="${profile.requires.serialisation?'Enter product serial':'Only if a separate product serial exists'}"></div></div>`}).join('')}</div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save identity register','data-save-sample-register-v1056','button next-action')}`,true);setTimeout(()=>{$('[data-save-sample-register-v1056]').onclick=async()=>{const set=new Set();for(const sm of samples){const v=$(`[data-v1056-sample-serial="${sm.serial}"]`).value.trim();if(profile.requires.serialisation&&!v){toast(`Formal serial is required for Sample ${sm.sampleNumber}.`,true);return}if(v){if(set.has(v)){toast(`Duplicate formal serial: ${v}`,true);return}set.add(v)}}const before=JSON.stringify(samples.map(x=>({id:x.serial,serialNumber:x.serialNumber})));samples.forEach(sm=>sm.serialNumber=$(`[data-v1056-sample-serial="${sm.serial}"]`).value.trim());const after=JSON.stringify(samples.map(x=>({id:x.serial,serialNumber:x.serialNumber})));if(before!==after){P.invalidateBuildReport(App.state,r,'Formal sample serial identity changed');P.audit(App.state,'Sample identity register updated','Request',requestId,before,after,'Automatic sample numbers and Lab IDs retained')};await persist();closeModal();render();toast('Sample identity register updated.')}},0)}
editSampleRegisterModal=editSampleRegisterModalV1056;

function controlPlanProductGroups(){const groups=new Map(),cps=(App.state.controlPlans||[]).filter(c=>c.status!=='Superseded');for(const cp of cps){const linked=(App.state.requests||[]).filter(r=>r.controlPlanId===cp.id||(cp.requestIds||[]).includes(r.id)),ids=[...new Set(linked.map(r=>r.productId).filter(Boolean))],key=ids.length===1?ids[0]:ids.length>1?'MULTI':'UNLINKED',product=ids.length===1?(App.state.products||[]).find(p=>p.id===ids[0]):null,label=product?`${product.family} · ${product.partNumber} Rev ${product.revision}`:ids.length>1?'Shared / multiple products':'Unlinked / library';if(!groups.has(key))groups.set(key,{key,label,productId:product?.id||null,cps:[]});groups.get(key).cps.push({cp,linked})}return [...groups.values()].sort((a,b)=>a.label.localeCompare(b.label))}
function qualityControlPlanCard(cp,linked){const chars=cp.characteristics||[],special=chars.filter(c=>c.classification),incomplete=special.filter(c=>!P.controlCharacteristicReady(c)),ready=!incomplete.length&&chars.length>0,approvalState=controlPlanApprovalState(cp);return `<div class="card quality-cp-card"><div class="section-title-row"><div><span class="eyebrow">${esc(cp.id)} · REV ${esc(cp.revision)}</span><h3>${esc(cp.name)}</h3><div class="subtle">${esc(cp.phase||'Prototype')} · owner ${esc(cp.owner||'—')} · ${linked.length} linked build${linked.length===1?'':'s'}</div></div>${status(cp.status)}</div><div class="quality-cp-kpis"><div><strong>${chars.length}</strong><span>Controls</span></div><div><strong>${special.length}</strong><span>SC / safety</span></div><div class="${incomplete.length?'bad-text':''}"><strong>${incomplete.length}</strong><span>Incomplete</span></div></div>${incomplete.length?`<div class="callout bad"><strong>Approval blocker:</strong> ${esc(incomplete.map(x=>x.characteristic).join(', '))} still need objective specification / method / reaction / evidence.</div>`:cp.status!=='Approved'?'<div class="callout warn"><strong>Definition complete.</strong> Independent review / approval can proceed.</div>':''}<div class="route-toolbar">${can('controlplan:edit')?btn(cp.status==='Approved'?'Revise Control Plan':'Edit Control Plan',`data-edit-control-plan="${cp.id}"`,'button small secondary'):''}${cp.status!=='Approved'&&ready?(approvalState.stage==='submit-review'?(can('controlplan:edit')||currentRole()==='administrator'?btn('Submit for independent review',`data-request-cp-review="${cp.id}"`,'button small next-action'):''):approvalState.canApprove?btn('Approve formally',`data-approve-cp="${cp.id}"`,'button small next-action'):approvalState.switchRole?btn(`Switch to ${esc(approvalState.switchName||roleLabel(approvalState.switchRole))}`,`data-switch-role="${approvalState.switchRole}"`,'button small next-action'):''):''}${linked[0]?btn('Open linked build',`data-open-request="${linked[0].id}" data-tab="controls"`,'button small secondary'):''}</div></div>`}
renderQualityControlPlans=function(){const groups=controlPlanProductGroups();return `<div class="quality-subhead"><div><span class="eyebrow">CONTROL PLAN GOVERNANCE</span><h2>Control Plans by product</h2><p>A Control Plan belongs to a defined product/configuration context. Grouping by product prevents unrelated controls from being treated as one approval population.</p></div></div><div class="section-stack">${groups.map((g,i)=>`<details class="card cp-product-group" ${i<3?'open':''}><summary><span><strong>${esc(g.label)}</strong><small>${g.cps.length} Control Plan${g.cps.length===1?'':'s'}</small></span><span class="pill">${g.cps.filter(x=>x.cp.status!=='Approved').length} pending</span></summary><div class="section-stack">${g.cps.map(x=>qualityControlPlanCard(x.cp,x.linked)).join('')}</div></details>`).join('')||'<div class="empty">No Control Plans.</div>'}</div>`};

function gageRRCalculate(rows,lsl=null,usl=null){const clean=rows.map(x=>({...x,value:Number(x.value)})).filter(x=>x.part&&x.operator&&Number.isFinite(x.value)),parts=[...new Set(clean.map(x=>x.part))],ops=[...new Set(clean.map(x=>x.operator))];if(parts.length<2||ops.length<2)return {valid:false,reason:'Use at least 2 parts and 2 operators.'};const cellCounts=[];for(const p of parts)for(const o of ops)cellCounts.push(clean.filter(x=>x.part===p&&x.operator===o).length);const trials=cellCounts[0];if(trials<2||cellCounts.some(n=>n!==trials))return {valid:false,reason:'Crossed Gage R&R requires a balanced design with the same ≥2 repeated trials for every part/operator cell.'};const mean=a=>a.reduce((n,x)=>n+x,0)/a.length,grand=mean(clean.map(x=>x.value)),partMean=new Map(parts.map(p=>[p,mean(clean.filter(x=>x.part===p).map(x=>x.value))])),opMean=new Map(ops.map(o=>[o,mean(clean.filter(x=>x.operator===o).map(x=>x.value))])),cellMean=new Map();for(const p of parts)for(const o of ops)cellMean.set(`${p}|${o}`,mean(clean.filter(x=>x.part===p&&x.operator===o).map(x=>x.value)));const np=parts.length,no=ops.length,r=trials,ssPart=no*r*parts.reduce((n,p)=>n+(partMean.get(p)-grand)**2,0),ssOp=np*r*ops.reduce((n,o)=>n+(opMean.get(o)-grand)**2,0),ssInt=r*parts.reduce((n,p)=>n+ops.reduce((q,o)=>q+(cellMean.get(`${p}|${o}`)-partMean.get(p)-opMean.get(o)+grand)**2,0),0),ssRepeat=clean.reduce((n,x)=>n+(x.value-cellMean.get(`${x.part}|${x.operator}`))**2,0),dfPart=np-1,dfOp=no-1,dfInt=(np-1)*(no-1),dfRepeat=np*no*(r-1),msPart=ssPart/dfPart,msOp=ssOp/dfOp,msInt=ssInt/dfInt,msRepeat=ssRepeat/dfRepeat,varRepeat=Math.max(msRepeat,0),varInteraction=Math.max((msInt-msRepeat)/r,0),varOperator=Math.max((msOp-msInt)/(np*r),0),varRepro=varOperator+varInteraction,varGRR=varRepeat+varRepro,varPart=Math.max((msPart-msInt)/(no*r),0),varTotal=varGRR+varPart,sd=x=>Math.sqrt(Math.max(x,0)),studyPct=varTotal>0?100*sd(varGRR)/sd(varTotal):0,tol=(Number.isFinite(Number(lsl))&&Number.isFinite(Number(usl))&&Number(usl)>Number(lsl))?Number(usl)-Number(lsl):null,tolerancePct=tol?100*(6*sd(varGRR))/tol:null,ndc=varGRR>0?Math.floor(1.41*sd(varPart)/sd(varGRR)):99;return {valid:true,n:clean.length,parts:np,operators:no,trials:r,grand,varRepeat,varOperator,varInteraction,varRepro,varGRR,varPart,varTotal,repeatability6s:6*sd(varRepeat),reproducibility6s:6*sd(varRepro),grr6s:6*sd(varGRR),studyPct,tolerancePct,ndc:Math.max(1,ndc),anova:{msPart,msOp,msInt,msRepeat}}}
function gageRRStudyStatus(s){if(s.status==='Approved')return '<span class="status good">✓ Approved</span>';if(s.status==='Review requested')return '<span class="status warn">● Review requested</span>';return '<span class="status neutral">— Draft</span>'}
function renderQualityMsa(){P.ensureEnterpriseModel(App.state);const rows=(App.state.gageRRStudies||[]).slice().sort((a,b)=>String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||'')));return `<div class="quality-subhead"><div><span class="eyebrow">MEASUREMENT SYSTEM ANALYSIS</span><h2>Gage R&R studies</h2><p>Capability evidence is only decision-ready when the measurement system has an approved, matching MSA study. Studies are scoped by product/configuration, characteristic, method, process and gage/equipment.</p></div>${btn('+ New Gage R&R','data-new-gage-rr','button next-action')}</div><div class="section-stack">${rows.map(s=>{const r=s.result||{},prod=(App.state.products||[]).find(p=>p.id===s.productId);return `<div class="card msa-study-card"><div class="section-title-row"><div><span class="eyebrow">${esc(s.id)}</span><h3>${esc(s.title||s.characteristic||'Gage R&R')}</h3><div class="subtle">${esc(prod?.family||s.productId||'Unscoped')} · ${esc(s.configuration||'—')} · ${esc(s.characteristic||'—')} · ${esc((App.state.equipment||[]).find(e=>e.id===s.equipmentId)?.name||s.equipmentId||'—')}</div></div>${gageRRStudyStatus(s)}</div>${r.valid?`<div class="quality-cp-kpis"><div><strong>${r.studyPct.toFixed(1)}%</strong><span>GR&R · study variation</span></div><div><strong>${r.tolerancePct==null?'—':r.tolerancePct.toFixed(1)+'%'}</strong><span>GR&R · tolerance</span></div><div><strong>${r.ndc}</strong><span>ndc</span></div></div><div class="grid cols-3"><div class="score-row"><span>Repeatability 6σ</span><strong>${r.repeatability6s.toFixed(4)}</strong></div><div class="score-row"><span>Reproducibility 6σ</span><strong>${r.reproducibility6s.toFixed(4)}</strong></div><div class="score-row"><span>Design</span><strong>${r.parts} parts × ${r.operators} operators × ${r.trials} trials</strong></div></div>`:`<div class="callout bad"><strong>Study design invalid:</strong> ${esc(r.reason||'Recalculate study.')}</div>`}<div class="route-toolbar" style="margin-top:10px">${s.status==='Draft'?btn('Submit for review',`data-gage-review="${s.id}"`,'button small next-action'):''}${s.status==='Review requested'?btn('Approve MSA',`data-gage-approve="${s.id}"`,'button small next-action'):''}</div></div>`}).join('')||'<div class="card"><div class="empty">No Gage R&R study has been recorded yet.</div></div>'}</div>`}
function gageRRModal(){const products=App.state.products||[],equipment=App.state.equipment||[],processes=App.state.processes||[];openModal('New Gage R&R study',`<div class="callout"><h3>Crossed, balanced Gage R&R</h3><p>Paste one row per observation. Required columns: part, operator, trial, value. LabOS rejects an unbalanced design instead of producing a misleading GR&R.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Product</label><select id="grrProduct">${products.map(p=>`<option value="${p.id}">${esc(p.family)} · ${esc(p.partNumber)}</option>`).join('')}</select></div><div class="field"><label>Configuration</label><input id="grrConfig" placeholder="Exact configuration / revision"></div><div class="field"><label>Characteristic</label><input id="grrChar" placeholder="e.g. Calibration offset"></div><div class="field"><label>Measurement method</label><input id="grrMethod" placeholder="Controlled method / gauge method"></div><div class="field"><label>Process</label><select id="grrProcess"><option value="">Not process-specific</option>${processes.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.id)}</option>`).join('')}</select></div><div class="field"><label>Gage / equipment</label><select id="grrEquipment"><option value="">Select gage</option>${equipment.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.id)}</option>`).join('')}</select></div><div class="field"><label>LSL (optional)</label><input id="grrLsl" type="number" step="any"></div><div class="field"><label>USL (optional)</label><input id="grrUsl" type="number" step="any"></div><div class="field full"><label>Observations · part,operator,trial,value</label><textarea id="grrRows" rows="12" placeholder="P01,Operator A,1,0.012\nP01,Operator A,2,0.011\nP01,Operator B,1,0.013\n..."></textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Create study','data-save-gage-rr','button next-action')}`,true);setTimeout(()=>{$('[data-save-gage-rr]').onclick=async()=>{const lines=$('#grrRows').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),rows=lines.map(line=>{const p=line.split(/[,;\t]/).map(x=>x.trim());return {part:p[0],operator:p[1],trial:p[2],value:p[3]}}),lsl=$('#grrLsl').value===''?null:Number($('#grrLsl').value),usl=$('#grrUsl').value===''?null:Number($('#grrUsl').value),result=gageRRCalculate(rows,lsl,usl);if(!result.valid){toast(result.reason,true);return}const rec={id:P.uid('GRR'),title:`${$('#grrChar').value.trim()} · Gage R&R`,productId:$('#grrProduct').value,configuration:$('#grrConfig').value.trim(),characteristic:$('#grrChar').value.trim(),method:$('#grrMethod').value.trim(),processId:$('#grrProcess').value,equipmentId:$('#grrEquipment').value,lsl,usl,rows,result,status:'Draft',createdBy:App.state.identity.name,createdAt:P.now(),updatedAt:P.now()};if(!rec.configuration||!rec.characteristic||!rec.method||!rec.equipmentId){toast('Configuration, characteristic, measurement method and gage/equipment are required.',true);return}App.state.gageRRStudies.push(rec);P.audit(App.state,'Gage R&R study created','MSA',rec.id,'—','Draft',`${rec.characteristic} · ${result.parts} parts × ${result.operators} operators × ${result.trials} trials`);await persist();closeModal();App.filters.qualityTab='msa';render();toast('Gage R&R study created as Draft.')}},0)}
function requestGageReview(id){const s=(App.state.gageRRStudies||[]).find(x=>x.id===id);if(!s)return;s.status='Review requested';s.reviewRequestedBy=App.state.identity.name;s.reviewRequestedAt=P.now();P.audit(App.state,'Gage R&R submitted for review','MSA',id,'Draft','Review requested',App.state.identity.name);persist().then(()=>render())}
function approveGageRR(id){const s=(App.state.gageRRStudies||[]).find(x=>x.id===id);if(!s)return;if(s.status!=='Review requested'){toast('Submit the study for review first.',true);return}const self=App.state.settings?.separationOfDuties&&s.createdBy===App.state.identity.name&&currentRole()!=='administrator';if(self){toast('Separation of duties prevents the study author from approving the same MSA study.',true);return}if(!['administrator','quality','metrology','approver','lab_manager'].includes(currentRole())){toast('Switch to Quality, Metrology, Lab Manager or Approver / Reviewer.',true);return}openModal(`Approve Gage R&R · ${s.id}`,`<div class="callout"><h3>Independent MSA review</h3><p>Confirm study design, scope and measurement-system result. Approval makes this study available to matching capability populations.</p></div><div class="field"><label>Review conclusion / evidence <b>required</b></label><textarea id="grrApproveNote"></textarea></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Approve MSA','data-confirm-grr-approve','button next-action')}`);setTimeout(()=>{$('[data-confirm-grr-approve]').onclick=async()=>{const note=$('#grrApproveNote').value.trim();if(!note){toast('Record the review conclusion.',true);return}s.status='Approved';s.approvedBy=App.state.identity.name;s.approvedAt=P.now();s.approvalRationale=note;P.audit(App.state,'Gage R&R approved','MSA',id,'Review requested','Approved',note);await persist();closeModal();render();toast('MSA study approved. Matching capability populations can now be decision-ready.')}},0)}
function matchingMsa(a){return (App.state.gageRRStudies||[]).find(s=>s.status==='Approved'&&s.productId===a.ctx.productId&&s.configuration===a.ctx.configuration&&(!s.processId||s.processId===a.ctx.processId)&&s.equipmentId===a.ctx.equipmentId&&String(s.characteristic).trim().toLowerCase()===String(a.characteristic).trim().toLowerCase()&&String(s.method).trim().toLowerCase()===String(a.method).trim().toLowerCase())||null}
const _capabilityStatusBadge1055=capabilityStatusBadge,_capabilityCard1055=capabilityCard;
