viewCalibrationCertificates=function(id){const e=App.state.equipment.find(x=>x.id===id),rows=(App.state.calibrationCertificates||[]).filter(c=>c.equipmentId===id).sort((a,b)=>String(b.completedAt).localeCompare(String(a.completedAt))),mayAdd=can('calibration:manage')||currentRole()==='administrator',mayApprove=['administrator','quality','metrology','lab_manager','approver'].includes(currentRole());openModal(`Calibration certificates · ${e.name}`,`<div class="table-wrap"><table class="data-table"><thead><tr><th>Certificate</th><th>Source / issuer</th><th>Dates</th><th>Evidence</th><th>Result</th><th>Formal approval</th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.certificateNo)}</strong></td><td>${esc(c.sourceType||'—')}<small>${esc(c.issuer||'—')}</small></td><td>${P.formatDate(c.completedAt)}<small>Due ${P.formatDate(c.nextDue)}</small></td><td>${evidenceDocumentLink(c,'Open certificate')}<small>${esc(c.referenceStandard||'')}</small></td><td>${status(c.result||c.status||'Recorded')}</td><td>${c.approvalStatus==='Approved'?`<span class="status good">✓ Approved</span><small>${esc(c.approvedBy||'')} · ${P.formatDateTime(c.approvedAt)}</small>`:c.approvalStatus==='Rejected'?'<span class="status bad">✕ Rejected</span>':`${status('Pending approval')}${mayApprove?btn('Review',`data-cal-cert-approve="${c.id}"`,'button tiny next-action'):''}`}</td></tr>`).join('')||'<tr><td colspan="6">No calibration certificate recorded.</td></tr>'}</tbody></table></div>`,`${btn('Close','data-modal-close','button')}${mayAdd?btn('+ Add certificate',`data-modal-add-cal="${id}"`,'button next-action'):''}`,true);setTimeout(()=>{const add=$('[data-modal-add-cal]');if(add)add.onclick=()=>addCalibrationCertificateModal(id);$$('[data-cal-cert-approve]').forEach(b=>b.onclick=()=>{closeModal();approveCalibrationCertificate(b.dataset.calCertApprove)})},0)};

const _readinessBlockerModal1055=readinessBlockerModal;
readinessBlockerModal=function(requestId,name){_readinessBlockerModal1055(requestId,name);setTimeout(()=>{const modal=$('#modalRoot .modal');if(!modal)return;let footer=modal.querySelector('.modal-footer');if(!footer){footer=document.createElement('div');footer.className='modal-footer';modal.appendChild(footer)}if(currentRole()==='administrator'&&!footer.querySelector('[data-v1056-readiness-exception]')){const b=document.createElement('button');b.className='button admin-exception';b.type='button';b.dataset.v1056ReadinessException='1';b.textContent='Administrator exception…';b.onclick=()=>{closeModal();adminExceptionModal('Build',requestId,'Lifecycle gate')};footer.prepend(b)}if(!footer.querySelector('[data-v1056-readiness-recheck]')){const b=document.createElement('button');b.className='button blocker-action';b.type='button';b.dataset.v1056ReadinessRecheck='1';b.textContent='Recheck blocker';b.onclick=()=>{const rs=new P.ReadinessService(App.state).evaluate(requestId),still=(rs.issues||[]).some(x=>x.name===name);closeModal();render();if(still){toast('Blocker remains open because the underlying evidence is still incomplete.',true);setTimeout(()=>readinessBlockerModal(requestId,name),50)}else toast(rs.ready?'Blocker cleared. Build Readiness is now satisfied.':'This blocker cleared; other readiness items remain.')};footer.appendChild(b)}},0)};
