  const active=(App.state.requests||[]).filter(r=>r.status!=='CLOSED'),ids=new Set((App.state.routes||[]).filter(rt=>active.some(r=>r.id===rt.requestId)).flatMap(rt=>(rt.steps||[]).map(s=>s.processId).filter(Boolean)));
  return (App.state.processes||[]).filter(p=>ids.has(p.id)&&(p.status!=='Released'||!(P.processGovernanceAssessment?p=>P.processGovernanceAssessment(p).ready:p=>p.workInstruction?.steps?.length)(p))).map(p=>{const gov=P.processGovernanceAssessment?P.processGovernanceAssessment(p):{issues:[]};return `${p.id} · ${p.name}${gov.ready?'':` · ${gov.issues.join(', ')}`}`});
